    // COMPLETE integer or the conversion fails
    const cut = t.trimStart().split(/[.,]/)[0];
    if (!/^[+-]?[0-9]+$/.test(cut)) return 0;
    const v = parseInt(cut, 10);
    return Number.isFinite(v) ? v : 0;
