      const scale = 10 ** (Math.floor(Math.log10(Math.abs(v))) + 1);
      const x = (v / scale) * 10 ** digits;
      let r = Math.round(x); // JS rounds half toward +inf...
      if (Math.abs(x % 1) === 0.5 && r % 2 !== 0) r -= 1;
