/**
 * The block types whose payload is `size` 4-byte instruction words.
 * @type {Object<number, boolean>}
 */
const IPOF_CODE_BLOCKS = {
  0x01: true,
  0x02: true,
  0x03: true,
  0x05: true,
  0x21: true,
  0x22: true,
  0x23: true,
  0x24: true,
  0x25: true,
};

