  const width =
    verHi === 1
      ? { 0x01: 1, 0x02: 2, 0x03: 4, 0x05: 8 }
      : {
          0x01: 1,
          0x02: 1,
          0x03: 2,
          0x04: 4,
          0x05: 8,
          0x07: 4,
          0x08: 4,
          0x09: 4,
        };
