;/* ==== core/remote-ui.js ==== */
/* exported showRemoteBar */

// Remote diagnostics -- the UI and the helper-side fetch shim. Split out of
// remote.js, which keeps the core Remote engine (signaling, WebRTC, session
// state and the owner-side security gate). This file is everything the user
// sees and the transparent fetch redirection on the helper's side:
//   - installRemoteHelperShim / uninstallRemoteHelperShim: route the helper's
//     car-touching fetches to the owner over the data channel
//   - showRemoteDialog: start/join a session
//   - remoteOverlay / showHelperWaiting / showOwnerConsole / showRemoteBar:
//     the full-screen session overlays and the persistent REMOTE badge
//   - resumeRemoteShare: re-arm a share that survived a reload
// It talks to the engine only through the global `Remote` (defined in
// remote.js, loaded first), and the engine calls back into these by name at
// session time -- both resolve through the shared global scope.

// ---- the helper's fetch interception ---------------------------------------
//
// Sits IN FRONT of the webshim fetch. Car routes (REMOTE_CAR_ROUTE, defined in
// remote.js since the owner-side gate uses it too) go to the owner over the
// data channel; every static route (screens, IR, tables, fault data) is
// answered locally by the shim exactly as always. So the helper's app is fully
// itself, and only the car reaches across.

/** The real window.fetch, saved while the helper shim is installed. @type {typeof fetch|null} */
let _remoteBaseFetch = null;

/**
 * Install the helper's fetch interception: car routes go to the owner over the
 * data channel, everything else is answered locally. Idempotent.
 * @returns {void}
 */
function installRemoteHelperShim() {
  if (_remoteBaseFetch) return;
  _remoteBaseFetch = window.fetch;
  window.fetch = async (input, init) => {
    const url = typeof input === 'string' ? input : (input && input.url) || '';
    const rel = url.replace(/^https?:\/\/[^/]+/, '');
    // role alone decides: while we are a helper, a car route goes to the
    // owner or fails, it never falls through to this machine's own shim
    // (which has no cable and would say so, misleadingly)
    if (Remote.role === 'helper' && REMOTE_CAR_ROUTE.test(rel)) {
      return Remote.request(rel, init);
    }
    return _remoteBaseFetch(input, init);
  };
  if (typeof document !== 'undefined') {
    document.body.classList.add('remote-helper');
  }
}
/**
 * Restore the real window.fetch, undoing {@link installRemoteHelperShim}.
 * @returns {void}
 */
function uninstallRemoteHelperShim() {
  if (!_remoteBaseFetch) return;
  window.fetch = _remoteBaseFetch;
  _remoteBaseFetch = null;
}

if (typeof window !== 'undefined') {
  // Remote itself is exported by remote.js (the engine); this file exports the
  // shim + UI it owns.
  window.installRemoteHelperShim = installRemoteHelperShim;
  window.uninstallRemoteHelperShim = uninstallRemoteHelperShim;
}

// ---- UI ---------------------------------------------------------------------

/**
 * Open the Remote session dialog: start a share (with an access level and a
 * confirm setting) or join one by code.
 * @returns {void}
 */
function showRemoteDialog() {
  if (typeof openModal !== 'function') return;
  const configured = !!Remote.base();
  const { overlay, close } = openModal(`
    <div class="modal" role="dialog" aria-modal="true" style="max-width:540px">
      <div class="modal-title">Remote session</div>
      <div class="modal-body" id="remote-body">
        ${
          configured
            ? `
        <p style="margin:0 0 14px;color:var(--ink-dim);font-size:13px">
          Share your car with someone, or connect to a shared car. The car
          stays on this machine. Only jobs cross the connection, and it
          is direct browser-to-browser once linked.</p>
        <div style="display:flex;gap:10px;flex-wrap:wrap" id="rm-choose">
          <button class="btn primary" id="rm-host">Share my car</button>
          <button class="btn" id="rm-join">Connect to a car</button>
        </div>

        <div id="rm-share-opts" style="display:none;margin-top:6px">
          <div style="font-weight:600;margin-bottom:4px">Share my car</div>
          <p style="margin:0 0 12px;color:var(--ink-dim);font-size:13px">
            What should the helper be able to do? These are enforced on this
            machine, the one at the car, not the helper's.</p>

          <div style="font-size:12px;color:var(--ink-dim);margin-bottom:5px">
            Access</div>
          <label class="rm-opt">
            <input type="radio" name="rm-access" value="rw" checked>
            <span><strong>Read + write.</strong> Read faults and live
              values, clear codes, run activations, code modules.</span></label>
          <label class="rm-opt">
            <input type="radio" name="rm-access" value="ro">
            <span><strong>Read only.</strong> Read faults and live
              values only. Writes and activations are refused.</span></label>

          <label class="rm-opt" style="margin-top:10px">
            <input type="checkbox" id="rm-confirm" checked>
            <span><strong>Confirm the helper's actions.</strong> You
              approve each write or activation before it reaches the car.
              Reads never prompt. <span style="color:var(--ink-dim)">Recommended.</span></span></label>

          <div style="display:flex;gap:10px;margin-top:14px">
            <button class="btn primary" id="rm-share-go">Get a code</button>
            <button class="btn" id="rm-share-back">Back</button>
          </div>
        </div>

        <div id="rm-join-row" style="display:none;margin-top:14px">
          <input id="rm-code" placeholder="SESSION CODE" maxlength="12"
            style="text-transform:uppercase;letter-spacing:.15em;
                   font-family:var(--mono);width:100%;padding:9px;
                   background:transparent;color:inherit;
                   border:1px solid var(--line)">
          <button class="btn primary" id="rm-join-go"
            style="margin-top:8px">Connect</button>
        </div>`
            : `
        <p style="color:var(--ink-dim);font-size:13px">Remote sessions need a
          signaling endpoint. Set <code>betaEndpoint</code> in Settings (the
          same worker the beta reports use), then reopen this.</p>`
        }
      </div>
      <div class="modal-actions">
        <button class="btn modal-cancel">Close<span class="modal-key">Esc</span></button>
      </div>
    </div>`);
  overlay.querySelector('.modal-cancel').onclick = () => close();
  if (!configured) return;

  const choose = overlay.querySelector('#rm-choose');
  const shareOpts = overlay.querySelector('#rm-share-opts');
  const joinRow = overlay.querySelector('#rm-join-row');

  overlay.querySelector('#rm-join').onclick = () => {
    shareOpts.style.display = 'none';
    joinRow.style.display = 'block';
    overlay.querySelector('#rm-code').focus();
  };
  // Share is now a two-step flow: pick the access level + confirm setting,
  // THEN get a code. The owner decides the session's ceiling up front.
  overlay.querySelector('#rm-host').onclick = () => {
    joinRow.style.display = 'none';
    choose.style.display = 'none';
    shareOpts.style.display = 'block';
  };
  overlay.querySelector('#rm-share-back').onclick = () => {
    shareOpts.style.display = 'none';
    choose.style.display = 'flex';
  };
  overlay.querySelector('#rm-share-go').onclick = async () => {
    const access =
      overlay.querySelector('input[name="rm-access"]:checked')?.value === 'ro'
        ? 'ro'
        : 'rw';
    const confirmActions =
      overlay.querySelector('#rm-confirm')?.checked !== false;
    try {
      const code = await Remote.host({ access, confirmActions });
      close();
      showOwnerConsole(code, { access, confirmActions });
    } catch (e) {
      overlay.querySelector('#remote-body').innerHTML =
        `<div class="modal-body">Could not start: ${esc(e.message)}</div>`;
    }
  };
  const go = async () => {
    const code = overlay.querySelector('#rm-code').value.trim();
    if (!code) return;
    const btn = overlay.querySelector('#rm-join-go');
    btn.disabled = true;
    btn.textContent = 'Connecting…';
    try {
      await Remote.join(code);
      close();
      // The channel is up but we are NOT in yet: show a blocking full-screen
      // wait until the owner admits. showRemoteBar/app come after admit.
      showHelperWaiting();
      if (typeof sbLeft !== 'undefined') {
        sbLeft.textContent = 'waiting for the owner to let you in…';
      }
    } catch (e) {
      btn.disabled = false;
      btn.textContent = 'Connect';
      overlay.querySelector('#rm-code').style.borderColor = '#d66';
      if (typeof sbLeft !== 'undefined') sbLeft.textContent = e.message;
    }
  };
  overlay.querySelector('#rm-join-go').onclick = go;
  overlay.querySelector('#rm-code').addEventListener('keydown', (e) => {
    if (e.key === 'Enter') go();
  });
}

// ---- full-screen remote overlays -------------------------------------------
// A single centred, blocking overlay used for the moments that need the user's
// whole attention on BOTH sides: the helper waiting to be admitted, and the
// owner admitting a helper or approving a write. Returns { close }.
/**
 * One centred, blocking full-screen overlay for the moments that need the
 * user's whole attention (helper waiting to be admitted; owner admitting or
 * approving a write).
 * @param {Object} opts
 * @param {'wait'|'admit'|'approve'} [opts.kind] - Visual variant.
 * @param {string} opts.title - Overlay title.
 * @param {string} [opts.body] - Trusted HTML body.
 * @param {Array<{label: string, cls?: string, fn?: () => void, keepOpen?: boolean}>} [opts.actions] - Buttons.
 * @returns {{el: HTMLElement, close: () => void}}
 */
function remoteOverlay({ kind, title, body, actions }) {
  document.getElementById('remote-overlay')?.remove();
  const el = document.createElement('div');
  el.id = 'remote-overlay';
  el.className = 'remote-overlay' + (kind ? ' ro-' + kind : '');
  el.innerHTML = `
    <div class="ro-card">
      ${kind === 'wait' ? '<div class="ro-spinner" aria-hidden="true"></div>' : ''}
      <div class="ro-title">${esc(title)}</div>
      <div class="ro-body">${body || ''}</div>
      <div class="ro-actions">${(actions || [])
        .map(
          (a, i) => `<button class="btn ${a.cls || ''}"
          data-i="${i}">${esc(a.label)}</button>`
        )
        .join('')}</div>
    </div>`;
  document.body.appendChild(el);
  const close = () => el.remove();
  (actions || []).forEach((a, i) => {
    const b = el.querySelector(`[data-i="${i}"]`);
    if (b)
      b.onclick = () => {
        if (a.keepOpen) a.fn();
        else {
          close();
          a.fn && a.fn();
        }
      };
  });
  return { el, close };
}

// HELPER: the full-screen "waiting to be admitted" screen, shown from the
// moment the channel connects until the owner admits (or declines / cancel).
/**
 * HELPER: the full-screen "waiting to be admitted" screen, up from the moment
 * the channel connects until the owner admits (or declines / cancel).
 * @returns {() => void} A closer.
 */
function showHelperWaiting() {
  const { close } = remoteOverlay({
    kind: 'wait',
    title: 'Waiting for the owner to let you in',
    body: `<p>You're connected to the shared car. The owner has to admit you
      before you can run anything.</p>`,
    actions: [
      {
        label: 'Cancel',
        cls: 'danger',
        fn: () => Remote.end('you cancelled the request'),
      },
    ],
  });
  return close;
}

// OWNER: a persistent console -- the code to share, a live log of what the
// helper runs on the car, and a big end button. This is the owner's window
// onto their own car while someone else drives it.
/**
 * OWNER: a persistent console -- the code to share, a live log of what the
 * helper runs, and an end button -- and the admit/approve hooks the engine
 * calls. Collapses to a pill.
 * @param {string} code - The session code to display.
 * @param {{access?: 'rw'|'ro', confirmActions?: boolean}} [opts] - The session policy (display only).
 * @returns {void}
 */
function showOwnerConsole(code, opts = {}) {
  document.getElementById('owner-console')?.remove();
  const el = document.createElement('div');
  el.id = 'owner-console';
  el.className = 'owner-console';
  el.innerHTML = `
    <div class="oc-head">
      <div>
        <div class="oc-title">Sharing your car</div>
        <div class="oc-sub">Give this code to the person connecting.</div>
      </div>
      <div class="oc-btns">
        <button class="btn" id="oc-min" title="Collapse to a pill">&#8211;</button>
        <button class="btn danger" id="oc-end">End session</button>
      </div>
    </div>
    <div class="oc-code" id="oc-code">${esc(code)}</div>
    <div class="oc-state" id="oc-state">waiting for someone to connect…</div>
    <div class="oc-log mono" id="oc-log"></div>
    <div class="oc-pill" id="oc-pill" title="Expand">
      <span class="rb-dot"></span><span class="mono">${esc(code)}</span>
      <span class="oc-pill-state" id="oc-pill-state">waiting</span>
    </div>`;
  document.body.appendChild(el);

  // ADMIT a connecting helper -- a full-screen prompt so the owner can't miss
  // it. Nothing runs until they decide. Shows the best-effort details of who is
  // asking. The promise the accept flow awaits resolves on the click.
  Remote.onAccept = (info) =>
    new Promise((resolve) => {
      const when = new Date(info.at || Date.now()).toLocaleTimeString();
      const ua =
        (info.ua || '').replace(/\s+/g, ' ').slice(0, 120) || 'unknown device';
      const ip = info.ip ? ` &middot; ${esc(info.ip)}` : '';
      remoteOverlay({
        kind: 'admit',
        title: 'Someone wants to connect to your car',
        body: `<div class="ro-detail mono">${esc(ua)}<br>connected ${esc(when)}${ip}</div>
        <p>They can read and (if you allow it) command your car. Only admit
        someone you are expecting.</p>`,
        actions: [
          { label: 'Admit', cls: 'primary', fn: () => resolve(true) },
          { label: 'Reject', cls: 'danger', fn: () => resolve(false) },
        ],
      });
    });

  // A FLASHING OPERATION the helper runs on this cable, as it happens: a
  // full-screen card with the stage and a bar, up until it finishes, with
  // the one thing the owner must not do while it runs. A write that is
  // interrupted leaves the module without a program.
  let opCard = null;
  Remote.onOperation = (ev) => {
    const warning = ev.write
      ? `<p class="ro-warning">Do not switch the ignition off, unplug the cable or close this page until it finishes. While a program is being written the module has no valid one, and a write that is interrupted can leave it needing a bench recovery.</p>`
      : `<p class="ro-warning">Keep the ignition on and the cable in until it finishes.</p>`;
    if (ev.phase === 'start') {
      opCard = remoteOverlay({
        kind: 'run',
        title: `${ev.label} is running on your car`,
        body: `<div class="ro-detail mono">${esc(ev.what || '')}</div>
          <div class="ro-progress"><div class="ro-bar" style="width:0%"></div></div>
          <div class="ro-detail ro-stage">Starting…</div>${warning}`,
        actions: [],
      });
      return;
    }
    if (!opCard) return;
    const stage = opCard.el.querySelector('.ro-stage');
    const bar = opCard.el.querySelector('.ro-bar');
    if (ev.phase === 'stage' && stage) {
      stage.textContent = ev.stage || '';
      if (bar) bar.style.width = '0%';
    } else if (ev.phase === 'progress') {
      if (bar) bar.style.width = `${Math.max(0, Math.min(100, ev.pct || 0))}%`;
      if (stage)
        stage.textContent = `${ev.stage ? `${ev.stage} ` : ''}${ev.pct}%`;
    } else if (ev.phase === 'done') {
      const secs = Math.round((ev.took || 0) / 1000);
      opCard = remoteOverlay({
        kind: ev.ok ? 'run' : 'approve',
        title: ev.ok ? `${ev.label} finished` : `${ev.label} failed`,
        body: `<div class="ro-detail mono">${esc(ev.what || '')}</div>
          <div class="ro-detail">${esc(ev.status || '')}${secs ? ` · ${secs} s` : ''}</div>
          ${ev.ok ? '' : ev.write ? '<p class="ro-warning">Leave the ignition on and tell the helper: the module may be holding an incomplete program, and the helper can write it again.</p>' : ''}`,
        actions: [
          { label: 'Close', cls: 'primary', fn: () => (opCard = null) },
        ],
      });
    }
  };

  // APPROVE a single write/actuator -- also full-screen. Only fires when the
  // session allows writes and confirm is on; reads never reach here.
  Remote.onGate = (j) =>
    new Promise((resolve) => {
      const act = j.action || null;
      const jobs = act && act.jobs && act.jobs.length ? act.jobs : [];
      remoteOverlay({
        kind: 'approve',
        title:
          act && act.label
            ? `Helper wants to press "${act.label}"`
            : 'Helper wants to run an action on your car',
        body: `<div class="ro-detail mono">${esc(j.sgbd || '')} &middot; ${esc(j.job || '')}${
          j.arg ? ` (${esc(String(j.arg).slice(0, 60))})` : ''
        }</div>${
          jobs.length
            ? `<div class="ro-detail">This key can send: <span class="mono">${esc(jobs.join(' · '))}</span></div>`
            : ''
        }
        <p>This writes to or activates hardware on the car. Allowing it covers
        everything this one key press sends; the next key asks again.</p>`,
        actions: [
          { label: 'Allow', cls: 'primary', fn: () => resolve(true) },
          { label: 'Deny', cls: 'danger', fn: () => resolve(false) },
        ],
      });
    });
  // the console sits over the bottom-right of the screen -- exactly where a
  // module's F-keys and readouts live. Collapse it to a pill and back.
  const setMin = (min) => {
    el.classList.toggle('oc-min', min);
    try {
      localStorage.setItem('bmweb.oc.min', min ? '1' : '0');
    } catch {}
  };
  el.querySelector('#oc-min').onclick = () => setMin(true);
  el.querySelector('#oc-pill').onclick = () => setMin(false);
  try {
    if (localStorage.getItem('bmweb.oc.min') === '1') setMin(true);
  } catch {}
  const logEl = el.querySelector('#oc-log');
  Remote.onLog = (text) => {
    const d = document.createElement('div');
    d.textContent = text;
    logEl.appendChild(d);
    logEl.scrollTop = logEl.scrollHeight;
  };
  Remote.onState = (s) => {
    const st = el.querySelector('#oc-state');
    if (!st) return;
    st.textContent =
      s === 'live'
        ? '● live: helper is connected'
        : s === 'connecting'
          ? 'waiting for the helper. The code above connects'
          : 'session ended';
    st.className = 'oc-state' + (s === 'live' ? ' oc-live' : '');
    const ps = el.querySelector('#oc-pill-state');
    if (ps) {
      ps.textContent =
        s === 'live' ? 'live' : s === 'connecting' ? 'waiting' : 'ended';
      ps.className = 'oc-pill-state' + (s === 'live' ? ' oc-live' : '');
    }
    if (s === 'closed') setTimeout(() => el.remove(), 1500);
  };
  el.querySelector('#oc-code').onclick = () => {
    navigator.clipboard?.writeText(code).catch(() => {});
    el.querySelector('#oc-code').classList.add('oc-copied');
  };
  el.querySelector('#oc-end').onclick = () => {
    Remote.end('you ended it');
  };
}

// HELPER: the red border + badge, so it is never ambiguous that these jobs
// touch someone else's car.
/**
 * HELPER: the red border + REMOTE badge (so it is never ambiguous that these
 * jobs touch someone else's car), plus the "waiting for the owner's Allow"
 * card and the disconnect button.
 * @returns {void}
 */
function showRemoteBar() {
  document.body.classList.add('remote-helper');
  if (document.getElementById('remote-badge')) return;
  const b = document.createElement('div');
  b.id = 'remote-badge';
  b.className = 'remote-badge';
  b.innerHTML = `<span class="rb-dot"></span>REMOTE
    <button class="rb-end" id="rb-end">disconnect</button>`;
  document.body.appendChild(b);
  // A write or activation waits on the owner's Allow, not on the car: the
  // same full-screen card the admit wait uses, up until the owner answers.
  // No buttons: the request is already with the owner, and their answer
  // (allow or deny) is what closes it.
  let awaitCard = null;
  Remote.onAwait = (waiting, path) => {
    if (waiting) {
      if (awaitCard) return;
      const op = /\/api\/flash\/([a-z0-9-]+)/.exec(String(path || ''));
      const m = /\/(run|clear|write|flash)\/([^/?]+)/.exec(String(path || ''));
      const what = op
        ? typeof flashOps !== 'undefined'
          ? flashOps.label(op[1])
          : op[1]
        : m
          ? decodeURIComponent(m[2])
          : 'this action';
      awaitCard = remoteOverlay({
        kind: 'wait',
        title: 'Waiting for the host to accept your request',
        body: `<div class="ro-detail mono">${esc(what)}</div>
          <p>This writes to or activates hardware on their car, so the owner
          has to allow it on their screen. Their answer closes this.</p>`,
        actions: [],
      });
      if (typeof sbLeft !== 'undefined')
        sbLeft.textContent = 'waiting for the host to accept your request…';
    } else if (awaitCard) {
      awaitCard.close();
      awaitCard = null;
    }
  };
  b.querySelector('#rb-end').onclick = () => {
    Remote.end('you disconnected');
  };
  Remote.onState = (s) => {
    if (s === 'live' && typeof sbLeft !== 'undefined') {
      sbLeft.textContent = 'connected: driving the shared car';
    }
    if (s === 'closed') {
      document.getElementById('remote-badge')?.remove();
      document.body.classList.remove('remote-helper');
      if (typeof sbLeft !== 'undefined')
        sbLeft.textContent = 'remote session ended';
    }
  };
}

// Auto-resume a share across a page reload. If the last load left an active
// share (owner, not yet expired), re-host it under the SAME code and bring the
// console back, so a refresh does not drop a session the owner set up and does
// not force them to re-share a new code. Called once at boot.
/**
 * Auto-resume an owner's share across a page reload: re-host under the same
 * code and bring the console back. No-op when there was no active share.
 * @returns {Promise<boolean>} Whether a share was resumed.
 */
async function resumeRemoteShare() {
  const saved = Remote.savedShare && Remote.savedShare();
  if (!saved || !Remote.base()) return false;
  try {
    const code = await Remote.resume(saved);
    if (typeof showOwnerConsole === 'function') {
      showOwnerConsole(code, {
        access: saved.access,
        confirmActions: saved.confirmActions,
      });
      if (Remote.onLog) Remote.onLog('reconnected — the same code still works');
    }
    return true;
  } catch (e) {
    // a dead endpoint or a rejected re-offer: drop the stored share quietly
    Remote._clearPersist && Remote._clearPersist();
    return false;
  }
}

if (typeof window !== 'undefined') {
  window.showRemoteDialog = showRemoteDialog;
  window.resumeRemoteShare = resumeRemoteShare;
}


;/* ==== core/print.js ==== */
// Theme- and layout-agnostic printing. The problem: printing the live app DOM
// drags the user's theme (aero/metal/inpa), its CSS custom properties, and the
// current layout mode onto the paper, so every user's printout looks different
// and often broken. The fix here: never print the styled app at all. At print
// time a screen hands printDoc() STRUCTURED content; we render it into a single
// .print-root container that carries its OWN fixed, light stylesheet -- it reads
// zero theme variables and no app layout classes. A lone @media print rule hides
// the whole app and shows only .print-root, so the output is byte-identical no
// matter what the screen looks like.
//
// A screen calls:
//   printDoc({
//     title:   'Short Engine',                       // big heading
//     subtitle:'E46 · 325i · Sedan',                 // optional line under it
//     meta:    [['Main group','11 Engine'], ...],    // key/value chips
//     sections:[ printImage(url,alt),
//                printTable(['No.','Part number','Description'], rows),
//                printBlocks([{t:'p',s:'...'},{t:'table',rows:[...]}]),
//                printHtml('<p>trusted, already-escaped</p>') ],
//     footer:  'BMW WDS · printed 2026-08-16',        // optional
//     landscape: true,                                // page orientation
//     onReady: () => {}                               // fires once images decoded
//   })
//
// Section builders return { html } (and optionally an async decode step); they
// all escape their inputs, so callers pass raw strings. Only printHtml() trusts
// its argument -- reserve it for markup a screen already built and escaped.

// ---- section builders -------------------------------------------------------

/**
 * One section of a print document, as the builders below produce it.
 * @typedef {Object} PrintSection
 * @property {string} html - The section's markup (already escaped).
 * @property {boolean} [needsImages] - The doc waits for images to decode first.
 * @property {boolean} [avoidBreak] - Keep the section on one page when possible.
 */

/**
 * A typed content block, the shape the ISTA test plans use.
 * @typedef {Object} PrintBlock
 * @property {'p'|'bullet'|'table'} t - Block kind.
 * @property {string} [s] - Text for a paragraph or bullet.
 * @property {string[][]} [rows] - Table rows; the first row is the header.
 */

// A figure. `url` may be an <img> src or (SVG string) inlined verbatim.
/**
 * A figure section.
 * @param {string} url - The image source.
 * @param {string} [alt] - Alt text.
 * @returns {PrintSection}
 */
function printImage(url, alt) {
  if (!url) return { html: '' };
  return {
    html: `<figure class="pr-fig"><img class="pr-img" src="${esc(url)}" alt="${esc(alt || '')}"></figure>`,
    // images must be decoded before print or they come out blank; the doc waits
    needsImages: true,
  };
}

// An inline SVG figure (the wiring diagrams): the markup is trusted (it's the
// document we loaded), and inlining keeps it lossless and printable.
/**
 * An inline SVG figure section (trusted markup).
 * @param {string} svgMarkup - The SVG document markup.
 * @returns {PrintSection}
 */
function printSvg(svgMarkup) {
  if (!svgMarkup) return { html: '' };
  return { html: `<figure class="pr-fig pr-fig-svg">${svgMarkup}</figure>` };
}

// A simple grid table. headers: [string]; rows: [[cell, cell, ...]]. Cells are
// escaped. Optional per-column class list aligns/sizes columns (e.g. 'pr-mono').
/**
 * A simple grid table section.
 * @param {string[]} headers - Column headers (empty for none).
 * @param {Array<Array<string|number|null>>} rows - Table rows; cells are escaped.
 * @param {string[]} [colClasses] - Per-column class names (e.g. 'pr-mono').
 * @returns {PrintSection}
 */
function printTable(headers, rows, colClasses) {
  const cls = (i) =>
    colClasses && colClasses[i] ? ` class="${colClasses[i]}"` : '';
  const thead =
    headers && headers.length
      ? `<thead><tr>${headers.map((h, i) => `<th${cls(i)}>${esc(h)}</th>`).join('')}</tr></thead>`
      : '';
  const body = (rows || [])
    .map(
      (r) =>
        `<tr>${r.map((c, i) => `<td${cls(i)}>${esc(c == null ? '' : c)}</td>`).join('')}</tr>`
    )
    .join('');
  return {
    html: `<table class="pr-table">${thead}<tbody>${body}</tbody></table>`,
  };
}

// Typed blocks, the shape the ISTA test plans use: {t:'p'|'bullet',s} and
// {t:'table',rows:[[...]]}. Rendered to fixed print markup, no app classes.
/**
 * Typed blocks rendered to fixed print markup.
 * @param {PrintBlock[]} blocks - The blocks.
 * @returns {PrintSection}
 */
function printBlocks(blocks) {
  const one = (b) => {
    if (!b) return '';
    if (b.t === 'p') return `<p class="pr-p">${esc(b.s)}</p>`;
    if (b.t === 'bullet') return `<p class="pr-p pr-bullet">${esc(b.s)}</p>`;
    if (b.t === 'table' && b.rows && b.rows.length) {
      const cols = Math.max(...b.rows.map((r) => r.length));
      const rows = b.rows
        .map((r, ri) => {
          const cells = [];
          for (let i = 0; i < cols; i++) {
            cells.push(
              `<${ri === 0 ? 'th' : 'td'}>${esc(r[i] || '')}</${ri === 0 ? 'th' : 'td'}>`
            );
          }
          return `<tr>${cells.join('')}</tr>`;
        })
        .join('');
      return `<table class="pr-table pr-table-grid">${rows}</table>`;
    }
    return '';
  };
  return { html: (blocks || []).map(one).join('') };
}

// A heading inside the body (chapter title within a section).
/**
 * A chapter heading section.
 * @param {string} text - The heading text (escaped).
 * @returns {PrintSection}
 */
function printHeading(text) {
  return { html: `<h2 class="pr-h2">${esc(text)}</h2>` };
}

// Escape hatch: markup the caller already built and escaped. Trusted input only.
/**
 * A section of trusted, already-escaped markup.
 * @param {string} html - The markup.
 * @returns {PrintSection}
 */
function printHtml(html) {
  return { html: html || '' };
}

// ---- the document -----------------------------------------------------------

// The self-contained print stylesheet. Everything the printout needs, defined
// from scratch in fixed light colours and real print units -- it names no theme
// custom property, so aero/metal/inpa and any layout mode all print the same.
/** The self-contained print stylesheet (fixed light colours, print units). @type {string} */
const PRINT_CSS = `
  #pr-root { display: none; }
  @media print {
    @page { margin: 8mm; }
    /* Only take over the sheet when WE built a print document (body.pr-active,
       set while #pr-root is mounted). Otherwise a bare Cmd+P prints the normal
       page rather than a blank one -- the hide-everything rule below would blank
       any screen that has no print handler. */
    /* The app runs as a fixed-viewport SPA (html/body are height:100% and
       overflow:hidden). Left as-is that clips the print to a SINGLE page -- a
       long table just gets cut off with no page 2. Release the height/overflow
       so content flows and paginates across sheets. */
    html, body.pr-active {
      height: auto !important; min-height: 0 !important;
      overflow: visible !important; position: static !important;
      background: #fff !important;
    }
    body.pr-active > *:not(#pr-root) { display: none !important; }
    body.pr-active #pr-root {
      display: block !important; position: static !important;
      height: auto !important; max-height: none !important; overflow: visible !important;
      color: #14181d; background: #fff;
      font: 13px/1.45 -apple-system, "Helvetica Neue", Arial, sans-serif;
    }
    #pr-root * { box-sizing: border-box; }
    .pr-head { border-bottom: 2px solid #14181d; padding-bottom: 9px; margin-bottom: 14px; }
    .pr-title { font-size: 20px; font-weight: 800; letter-spacing: .01em; margin: 0; }
    .pr-subtitle { color: #555; font-size: 12.5px; margin-top: 3px; }
    .pr-meta { margin-top: 9px; display: flex; flex-wrap: wrap; gap: 6px 18px; font-size: 11px; color: #333; }
    .pr-meta b { color: #14181d; font-weight: 700; }
    .pr-section { margin: 0 0 14px; }
    .pr-section.avoid-break { page-break-inside: avoid; }
    .pr-h2 { font-size: 14px; font-weight: 700; margin: 14px 0 6px;
             border-left: 4px solid #c0392b; padding-left: 8px; page-break-after: avoid; }
    /* figures: never overflow the sheet; a big diagram scales down to fit */
    .pr-fig { margin: 0 0 12px; text-align: center; page-break-inside: avoid; }
    /* fill the sheet width: ETK exploded views are small rasters, so let them
       scale up to the content width -- bigger and a touch soft reads far better
       on paper than tiny and sharp. Cap the height so a tall diagram still fits. */
    .pr-img { width: 100%; max-height: 21cm; height: auto; object-fit: contain; }
    .pr-fig-svg svg { width: 100% !important; height: auto !important; max-height: 17cm; }
    .pr-fig-svg { border: 1px solid #999; padding: 4mm; }
    /* tables: a long table paginates; its header repeats atop each page */
    .pr-table { width: 100%; border-collapse: collapse; font-size: 12px; }
    .pr-table thead { display: table-header-group; }
    /* The fault report drives every module table from ONE shared <colgroup>
       (screens/sweep/report.js faultColumns). table-layout:fixed makes the
       browser honour those widths exactly instead of auto-sizing per block, so
       Code/Type/Count/State sit at the same x-position in every module table
       and on every printed page. Description takes the remaining width. */
    .pr-fault-table { table-layout: fixed; }
    .pr-fault-table td, .pr-fault-table th { overflow-wrap: anywhere; }
    /* a fault row and its freeze-frame row must not split across a page */
    .pr-faultrow, .pr-envtr { page-break-inside: avoid; break-inside: avoid; }
    .pr-table th { text-align: left; font-size: 10px; text-transform: uppercase; letter-spacing: .04em;
                   color: #666; border-bottom: 1px solid #bbb; padding: 4px 6px; }
    .pr-table td { padding: 4px 6px; border-bottom: 1px solid #e4e4e4; vertical-align: top; }
    .pr-table tr { page-break-inside: avoid; }
    .pr-mono { font: 600 11.5px "SF Mono", Menlo, Consolas, monospace; white-space: nowrap; }
    /* a code cell carrying its raw fault word on a second line: pre-line keeps
       the newline the caller put in, which plain .pr-mono would collapse */
    .pr-code2 { font: 600 11.5px "SF Mono", Menlo, Consolas, monospace;
                white-space: pre-line; line-height: 1.35;
                width: 128px; max-width: 128px; overflow-wrap: anywhere; }
    .pr-num { text-align: right; white-space: nowrap; }
    .pr-table-grid { margin: 6px 0; border: 1px solid #ccc; }
    .pr-table-grid th, .pr-table-grid td { border: 1px solid #ddd; padding: 3px 6px; }
    .pr-table-grid th { background: #f3f3f3; }
    /* freeze-frame snapshot under a fault table: a two-column key/value list
       that flows into as many columns as the page width allows, so eight values
       take a few lines instead of a full page of near-empty rows */
    .pr-env { margin: 4px 0 10px; padding: 5px 8px; border-left: 3px solid #bbb;
              background: #fafafa; page-break-inside: avoid; break-inside: avoid;
              display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1px 22px; }
    /* env grid riding inside the fault table, under its own code's row */
    .pr-envtr td { padding: 0 0 8px; border-bottom: 1px solid #e4e4e4; }
    .pr-envtr .pr-env { margin: 2px 0 0; }
    .pr-env-head { grid-column: 1 / -1; font-size: 9.5px; text-transform: uppercase;
                   letter-spacing: .05em; color: #777; margin-bottom: 3px; }
    /* each label:value pair is its own two-track sub-grid, so the value can
       never drop onto a line of its own away from its label */
    .pr-env-row { display: grid; grid-template-columns: auto 1fr; align-items: baseline;
                  column-gap: 10px; min-width: 0; padding: 1px 0; font-size: 11px;
                  page-break-inside: avoid; break-inside: avoid; }
    .pr-env-k { color: #555; white-space: nowrap; }
    .pr-env-v { font: 600 11px "SF Mono", Menlo, Consolas, monospace; color: #14181d;
                text-align: right; overflow-wrap: anywhere; }
    /* a module screen: INPA's 80-column grid as printed text, or its rows */
    .pr-screen { font: 10.5px/1.35 "SF Mono", Menlo, Consolas, monospace; white-space: pre;
                 margin: 0; padding: 8px 10px; border: 1px solid #ccc; background: #fafafa;
                 color: #14181d; overflow: hidden; }
    .pr-screen-table td { font-size: 12px; }
    .pr-screen-table td:first-child { width: 46%; color: #333; }
    .pr-screen-table .pr-unit { color: #666; white-space: nowrap; }
    .pr-screen-table .pr-note { color: #555; padding-top: 6px; }
    .pr-screen-table tr.pr-band td { border-top: 2px solid #ddd; padding-top: 7px; }
    /* the F-key bar under a printed screen: ten slots, a Shift row when needed */
    .pr-keys { margin: 6px 0 0; }
    .pr-fkeys { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 4px; margin-top: 4px; }
    .pr-fkey { display: flex; flex-direction: column; gap: 1px; min-height: 30px; padding: 4px 5px;
               border: 1px solid #ccc; border-radius: 4px; background: #fafafa; min-width: 0; }
    .pr-fkey.empty { background: #fff; border-color: #e2e2e2; }
    .pr-fkey-k { font: 600 8.5px "SF Mono", Menlo, Consolas, monospace; color: #777; }
    .pr-fkey-l { font-size: 10px; font-weight: 600; line-height: 1.2; overflow-wrap: anywhere; }
    .pr-fkey-s { font-size: 8.5px; color: #666; line-height: 1.2; overflow-wrap: anywhere; }
    /* the INPA layout's bar: key numbers over flat boxes, captions centred */
    .pr-ikeys { margin-top: 6px; }
    .pr-ikey-nums, .pr-ikey-btns { display: grid; grid-template-columns: repeat(10, minmax(0, 1fr)); gap: 4px; }
    .pr-ikey-num { font: 700 8.5px -apple-system, "Helvetica Neue", Arial, sans-serif; color: #888; text-align: center; line-height: 12px; }
    .pr-ikey { display: block; height: 22px; line-height: 22px; padding: 0 3px; border: 1px solid #bbb; border-radius: 3px;
               background: #f3f3f3; font-size: 10px; font-weight: 700; text-align: center; white-space: nowrap;
               overflow: hidden; text-overflow: ellipsis; min-width: 0; }
    .pr-ikey.empty { background: #fff; border-color: #e2e2e2; }
    /* text blocks */
    .pr-p { margin: 0 0 6px; }
    .pr-bullet { padding-left: 16px; position: relative; }
    .pr-bullet::before { content: "•"; position: absolute; left: 4px; color: #c0392b; }
    .pr-footer { margin-top: 16px; padding-top: 8px; border-top: 1px solid #ddd;
                 font-size: 10px; color: #999; }
  }`;

// inject the print stylesheet once
/**
 * Inject the print stylesheet into the document head (once).
 * @returns {void}
 */
function ensurePrintCss() {
  if (document.getElementById('pr-css')) return;
  const s = document.createElement('style');
  s.id = 'pr-css';
  s.textContent = PRINT_CSS;
  document.head.appendChild(s);
}

// window.print() is a no-op inside a WKWebView (no dialog behind it), so the Mac
// app runs an NSPrintOperation over the live view; the browser build's dialog is
// real. The promise resolves when the panel closes (native) or immediately (web).
/**
 * Open the print dialog: the native shell's print operation, or window.print().
 * @returns {Promise<void>} Settles when the panel closes (native) or at once (web).
 */
function triggerPrint() {
  if (window.bmweb && typeof window.bmweb.printPage === 'function') {
    return window.bmweb.printPage().catch(() => {});
  }
  window.print();
  return Promise.resolve();
}

/**
 * What a screen hands printDoc().
 * @typedef {Object} PrintDocOptions
 * @property {string} [title] - Big heading (defaults to the app name).
 * @property {string} [subtitle] - Line under the title.
 * @property {Array<[string, string]>} [meta] - Key/value chips.
 * @property {Array<PrintSection|string>} [sections] - Sections in order; falsy entries are skipped.
 * @property {string|null} [footer] - Footer text; omitted when null, defaults to the app + date.
 * @property {boolean} [landscape] - Page orientation.
 * @property {() => void} [onReady] - Fires once images have decoded, before the dialog.
 */

// Build the print document, print it, and tear it down afterwards. Returns a
// promise that settles when printing is done (or abandoned).
/**
 * Build the print document, print it, and tear it down afterwards.
 * @param {PrintDocOptions} opts - The document.
 * @returns {Promise<void>} Settles when printing is done (or abandoned).
 */
function printDoc(opts) {
  ensurePrintCss();
  const o = opts || {};
  const sections = (o.sections || []).filter(Boolean);
  const bodyHtml = sections
    .map((sec) => {
      const inner = typeof sec === 'string' ? sec : sec.html || '';
      if (!inner) return '';
      return `<section class="pr-section${sec.avoidBreak ? ' avoid-break' : ''}">${inner}</section>`;
    })
    .join('');

  const meta = (o.meta || [])
    .filter(Boolean)
    .map(([k, v]) => `<span>${esc(k)} <b>${esc(v)}</b></span>`)
    .join('');
  const app = typeof APP_NAME === 'string' ? APP_NAME : 'BMWeb';
  const footer =
    o.footer != null
      ? o.footer
      : `${app} · printed ${new Date().toLocaleDateString()}`;

  const root = document.createElement('div');
  root.id = 'pr-root';
  root.innerHTML = `
    <div class="pr-head">
      <h1 class="pr-title">${esc(o.title || app)}</h1>
      ${o.subtitle ? `<div class="pr-subtitle">${esc(o.subtitle)}</div>` : ''}
      ${meta ? `<div class="pr-meta">${meta}</div>` : ''}
    </div>
    ${bodyHtml}
    ${footer ? `<div class="pr-footer">${esc(footer)}</div>` : ''}`;

  // orientation is a per-print @page choice; a tiny scoped style toggles it
  const pageStyle = document.createElement('style');
  pageStyle.textContent = `@media print { @page { size: ${o.landscape ? 'landscape' : 'portrait'}; } }`;

  document.body.appendChild(root);
  document.head.appendChild(pageStyle);
  document.body.classList.add('pr-active'); // gates the @media print takeover

  let done = false;
  const cleanup = () => {
    if (done) return;
    done = true;
    root.remove();
    pageStyle.remove();
    document.body.classList.remove('pr-active');
    window.removeEventListener('afterprint', cleanup);
  };
  window.addEventListener('afterprint', cleanup);

  // wait for any <img> to decode, else it prints blank; cap the wait so a slow
  // or broken image never hangs the print.
  const imgs = [...root.querySelectorAll('img')];
  const ready = imgs.length
    ? Promise.race([
        Promise.all(
          imgs.map((im) =>
            im.complete ? Promise.resolve() : im.decode().catch(() => {})
          )
        ),
        new Promise((r) => setTimeout(r, 4000)),
      ])
    : Promise.resolve();

  return ready.then(() => {
    if (typeof o.onReady === 'function') {
      try {
        o.onReady();
      } catch {}
    }
    const p = triggerPrint();
    setTimeout(cleanup, 20000); // last resort if afterprint never fires
    return p.then(cleanup, cleanup);
  });
}

// The current screen's Print action, if it declared one via setActions. Matched
// by kind/label/hotkey so screens don't need to know about this interceptor.
/**
 * The current screen's Print action from the F-key bar, or null.
 * @returns {{label: string, fn: () => void, kind?: string, key?: string}|null}
 */
function currentPrintAction() {
  const bar = typeof actionBar !== 'undefined' ? actionBar : null;
  const list = (bar && bar.current) || [];
  const fromBar = list.find(
    (a) =>
      a && a.fn && (a.kind === 'print' || a.label === 'Print' || a.key === 'p')
  );
  if (fromBar) return fromBar;
  // a module view prints its sheet whether or not the script put a Print
  // key on this menu (INPA's own F9 is per menu; the shortcut is not)
  if (
    typeof window !== 'undefined' &&
    typeof window.ipoPrintCurrent === 'function' &&
    typeof window.ipoPrintAvailable === 'function' &&
    window.ipoPrintAvailable()
  ) {
    return {
      label: 'Print',
      kind: 'print',
      fn: () => window.ipoPrintCurrent(),
    };
  }
  return null;
}

// Route the browser's native Cmd/Ctrl+P to the active screen's clean print, so
// the everyday print shortcut produces the theme-agnostic sheet -- not a blank
// page (the app's own action bar ignores Cmd-modified keys). Screens with no
// Print action fall through to the browser's normal print (body isn't pr-active,
// so the live page prints as-is).
/**
 * Route Cmd/Ctrl+P to the active screen's Print action (capture phase).
 * @returns {void}
 */
function installPrintHotkey() {
  window.addEventListener(
    'keydown',
    (e) => {
      const p = e.key === 'p' || e.key === 'P';
      if (!p || !(e.metaKey || e.ctrlKey) || e.altKey || e.shiftKey) return;
      if (document.getElementById('pr-root')) return; // a print is already staged
      const act = currentPrintAction();
      if (!act) return; // let the native dialog run
      e.preventDefault();
      // Flag the Cmd/Ctrl+P origin so an action that has nothing to print yet
      // (a Print listed on a menu before anything was read) can fall through to
      // the native dialog instead of no-opping and swallowing the shortcut.
      window.__printViaHotkey = true;
      try {
        act.fn();
      } finally {
        // clear on the next tick, after fn() has read it (fn may be async, but it
        // reads the flag synchronously before its first await)
        setTimeout(() => {
          window.__printViaHotkey = false;
        }, 0);
      }
    },
    true
  ); // capture, to beat the app's own key handler and the dialog
}

if (typeof window !== 'undefined') {
  window.printDoc = printDoc;
  window.installPrintHotkey = installPrintHotkey;
  window.printImage = printImage;
  window.printSvg = printSvg;
  window.printTable = printTable;
  window.printBlocks = printBlocks;
  window.printHeading = printHeading;
  window.printHtml = printHtml;
  window.triggerPrint = triggerPrint;
}


