  const batOn = st.battery != null;
  const ignOn = st.ignition === true;
  bs.className = 'inpa-kl-led' + (batOn ? ' on' : '');
  bv.textContent = batOn ? 'on' : 'off';
  is.className = 'inpa-kl-led' + (ignOn ? ' on' : '');
