    when(MSP_VAR_COOLANT, cfg.coldWarmC, MSP_BGE, cfg.coldRpm);
  if (cfg.oilC != null)
    when(MSP_VAR_OIL, cfg.oilC, MSP_BLT, cfg.oilRpm, () => {
      li(11, 1);
      emit(mspD(38, 11, 13, MSP_VAR_OIL_WARNING)); // stb r11,warning(r13)
    });
