    if (!r)
      throw new Error(
        `one-click: the DME did not answer a read at 0x${at.toString(16)}`
      );
    if (r[0] !== 0x63 || r.length < n + 1)
      throw new Error(
        `one-click: the DME refused a read at 0x${at.toString(16)}`
      );
