    const gmFmt = gmValid ? '' : CodingZcs.formatGm(state.gm);
    const saFmt = saValid ? '' : CodingZcs.formatSa(state.sa);
    const vnFmt = vnValid ? '' : CodingZcs.formatVn(state.vn);

