    const frag = document.createDocumentFragment();
    for (const g of groups) {
      if (shown >= LOOKUP_MAX) break;
      const card = lookupResultGroup(g, LOOKUP_MAX - shown);
      frag.appendChild(card.el);
      shown += card.shown;
    }
    results.appendChild(frag);
