    const docs = wiringComponentDocs(ctx.index, m[1]);
    if (!docs.length) return;
    const rank = (e) => {
      const r = WIRING_LOCATE_ORDER.indexOf(e.kind);
      return r < 0 ? WIRING_LOCATE_ORDER.length : r;
    };
    const hit = docs.slice().sort((x, y) => rank(x) - rank(y))[0];
