/**
 * The document pane for a WDS leaf: a schematic or a description. Reflects
 * the open diagram in the URL so it's a shareable deep link
 * (#apps/wiring/<CHASSIS>/<DOC>); best-effort, the viewer works without it.
 * @param {WiringViewCtx} ctx - the open view
 * @param {WiringTabEntry} entry - the leaf's tab entry
 * @returns {void}
 */
function wiringRenderDocument(ctx, entry) {
  ctx.atIndex = ctx.index.findIndex((e) => e.doc === entry.doc);
  if (typeof routeSetWiringDoc === 'function' && entry && entry.doc) {
    // the filtered vehicle rides along, so a reload keeps the filter
    const vin =
      typeof wiringVinHit !== 'undefined' && wiringVinHit && wiringVinHit.vin
        ? wiringVinHit.vin
        : null;
    routeSetWiringDoc(ctx.chassisId, entry.doc, vin);
  }
  // ONE PANE AT A TIME ON A PHONE: below 760px the CSS hides the unselected
  // pane, so loading into it means a 0x0 stage. Switch to it; no-op on
  // desktop.
  if (wiringIsPhone()) ctx.setPane('doc', false);
  const doc = wiringDoc(ctx.data, entry.doc);
  const viewEl = ctx.viewEl;
  viewEl.innerHTML = '';
  const bar = wiringDocBar(
    entry.name,
    WIRING_KIND_LABEL[entry.kind] || entry.kind
  );
  viewEl.appendChild(bar);

  setActions(ctx.browseActions); // reset; a schematic adds its zoom keys
  if (!doc) {
    viewEl.insertAdjacentHTML(
      'beforeend',
      `<div class="empty"><div>This document is not in the WDS release the ` +
        `data was built from.</div></div>`
    );
    return;
  }
  if (doc.type === 'html') {
    wiringRenderDescription(ctx, bar, doc);
    return;
  }
  wiringRenderSchematic(ctx, bar, doc);
  sbLeft.textContent = entry.name;
}


;/* ==== screens/wiring/share-print.js ==== */
/**
 * @file Sharing and printing a document: the Share button copies the current
 * deep link, and Print hands the schematic or description to the shared
 * print helper as a clean sheet.
 */

/* exported
   wiringShareButton, printWiring */

/** How long the Share button shows its "Copied" confirmation, ms. */
const WIRING_COPY_FLASH_MS = 1600;
/** A schematic wider than this many times its height is sliced for print. */
const WIRING_PRINT_SLICE_ASPECT = 1.8;
/** The most slices a schematic is cut into for print. */
const WIRING_PRINT_MAX_SLICES = 3;
/** Overlap between adjacent print slices, as a fraction of a slice's width. */
const WIRING_PRINT_SLICE_OVERLAP = 0.03;

/**
 * A Share button for a document bar or the zoom controls.
 * @param {boolean} classic - INPA mode: WDS's button class
 * @returns {HTMLButtonElement}
 */
function wiringShareButton(classic) {
  const share = document.createElement('button');
  share.className = (classic ? 'wds-btn' : 'btn wiring-fit') + ' wiring-share';
  share.textContent = 'Share';
  share.title = 'Copy a link to this document';
  share.onclick = () => wiringShareCurrent(share);
  return share;
}

/**
 * Copy text to the clipboard: the async clipboard API where it exists, else
 * a hidden-textarea copy (file://, older browsers).
 * @param {string} text - what to copy
 * @returns {Promise<boolean>} whether the copy succeeded
 */
async function wiringCopyText(text) {
  try {
    if (navigator.clipboard && navigator.clipboard.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch (e) {
    /* fall through to the textarea copy */
  }
  try {
    const ta = document.createElement('textarea');
    ta.value = text;
    ta.style.position = 'fixed';
    ta.style.opacity = '0';
    document.body.appendChild(ta);
    ta.select();
    const ok = document.execCommand('copy');
    ta.remove();
    return ok;
  } catch (e) {
    return false;
  }
}

/**
 * Copy a shareable link to the document on screen. The app already reflects
 * the open document in the address bar (#apps/wiring/<CHASSIS>/<DOC>), so the
 * link is just the current URL. Flash the button to confirm the copy.
 * @param {HTMLButtonElement | null} btn - the Share button to flash
 * @returns {Promise<void>}
 */
async function wiringShareCurrent(btn) {
  const ok = await wiringCopyText(location.href);
  if (!btn) return;
  const original = btn.textContent;
  btn.textContent = ok ? '✓ Copied' : 'Copy failed';
  btn.classList.toggle('copied', ok);
  clearTimeout(btn._copyTimer);
  btn._copyTimer = setTimeout(() => {
    btn.textContent = original;
    btn.classList.remove('copied');
  }, WIRING_COPY_FLASH_MS);
}

/**
 * The print section for a schematic. A WDS schematic is a wide strip (4:1
 * and wider). Width-fitted to one sheet -- even landscape -- it prints a few
 * cm tall with the lower page empty. Slice a wide strip into stacked
 * full-width segments, each with a little overlap so a component at a cut
 * shows whole on one of the two sides; every segment then prints 2-3x
 * larger.
 * @param {SVGSVGElement} svg - the live schematic
 * @returns {{html: string}}
 */
function wiringPrintSection(svg) {
  // clone so restoring the home viewBox for print doesn't disturb the live one
  const clone = svg.cloneNode(true);
  if (clone.dataset.homeViewbox)
    clone.setAttribute('viewBox', clone.dataset.homeViewbox);
  clone.removeAttribute('style'); // drop any on-screen zoom transform
  const vb = (clone.getAttribute('viewBox') || '').split(/[\s,]+/).map(Number);
  const aspect = vb.length === 4 && vb[3] > 0 ? vb[2] / vb[3] : 1;
  const slices = Math.min(
    WIRING_PRINT_MAX_SLICES,
    Math.max(1, Math.round(aspect / WIRING_PRINT_SLICE_ASPECT))
  );
  if (slices <= 1) return printSvg(clone.outerHTML);
  const w = vb[2] / slices,
    pad = w * WIRING_PRINT_SLICE_OVERLAP;
  const parts = [];
  for (let i = 0; i < slices; i++) {
    const s = clone.cloneNode(true);
    const x0 = Math.max(vb[0], vb[0] + i * w - pad);
    const x1 = Math.min(vb[0] + vb[2], vb[0] + (i + 1) * w + pad);
    s.setAttribute('viewBox', `${x0} ${vb[1]} ${x1 - x0} ${vb[3]}`);
    s.setAttribute('preserveAspectRatio', 'xMidYMid meet');
    parts.push(`<figure class="pr-fig pr-fig-svg">${s.outerHTML}</figure>`);
  }
  return { html: parts.join('') };
}

/**
 * Print the DOCUMENT via the shared theme-agnostic helper (core/print.js): a
 * clean sheet built from the diagram/description, not the styled app. A
 * wiring diagram prints as its inlined SVG (whole circuit, not the zoomed
 * view); a description prints as its HTML. Either way the printout ignores
 * the current theme and layout entirely.
 * @param {string} chassisId - chassis code, for the sheet's meta and footer
 * @returns {void}
 */
function printWiring(chassisId) {
  const stage = document.querySelector('.wiring-stage');
  const svg = stage && stage.querySelector('svg');
  const doc = document.querySelector('.wiring-doc');
  const title = document.querySelector('.wiring-title');
  const kind = document.querySelector('.wiring-kind');
  const titleText = (title && title.textContent) || 'Wiring diagram';
  const kindText = (kind && kind.textContent) || 'Wiring diagram';

  let section;
  if (svg) section = wiringPrintSection(svg);
  else if (doc)
    section = printHtml(doc.innerHTML); // a description document
  else section = printHtml('');

  printDoc({
    title: titleText,
    meta: [
      ['Vehicle', dispChassis(chassisId)],
      ['Type', kindText],
    ],
    sections: [section],
    landscape: !!svg, // a diagram wants landscape; a description reads portrait
    footer: `BMWeb · ${dispChassis(chassisId)} · printed ${new Date().toLocaleDateString()}`,
  });
}


;/* ==== screens/wiring/picker.js ==== */
/**
 * @file Wiring as its own section: the landing page where the car is picked
 * (or identified by VIN) rather than arriving via a chassis.
 */

/* exported
   showWiringChassis, wiringClassic */

/** How many chassis get a number key on the picker's F-key bar. */
const WIRING_PICKER_HOTKEYS = 9;

/**
 * One car on the picker: an F-key row in INPA mode, a card otherwise.
 * @param {string} id - chassis code
 * @param {number} i - position in the list (numbers the F-key row)
 * @param {boolean} classic - the INPA skin is on (WDS chrome)
 * @returns {HTMLButtonElement}
 */
function wiringChassisCard(id, i, classic) {
  const tag = (typeof CHASSIS_TAG === 'object' && CHASSIS_TAG[id]) || 'BMW';
  const card = document.createElement('button');
  if (classic) {
    // INPA idiom: an F-key list, not cards
    card.className = 'inpa-fn';
    card.innerHTML =
      `<span class="inpa-fn-key">&lt; F${i + 1} &gt;</span>` +
      `<span class="inpa-fn-label">${esc(dispChassis(id))} · ${esc(tag)}</span>`;
  } else {
    card.className = 'chassis-card';
    card.innerHTML = `
        <div class="chassis-code">${esc(dispChassis(id))}</div>
        <div class="chassis-tag">${esc(tag)}</div>
        <div class="chassis-arrow">→</div>`;
  }
  card.onclick = () => showWiring(id);
  return card;
}

/**
 * The note shown when no car ships wiring. NOT an error (errorBlock's
 * cable/ignition advice would be irrelevant): the hosted site just can't
 * carry 1.1 GB over the GitHub Pages cap.
 * @returns {HTMLDivElement}
 */
function wiringAbsentNote() {
  const note = document.createElement('div');
  note.className = 'empty wiring-absent';
  note.innerHTML = `
      <div class="empty-big">No wiring data in this build</div>
      <div>The diagrams come from BMW's WDS, which is a separate download and
           not part of this repository.</div>
      <div style="font-size:12px;color:var(--ink-faint)">To add them:
           <code>scripts/setup/fetch-wds.sh</code> then
           <code>tools/wds_import.py --wds vendor/WDS</code>.</div>`;
  return note;
}

/**
 * Whether wiring wears WDS's own look: the classic layout (the top bar's
 * switch) or the INPA skin.
 * @returns {boolean}
 */
function wiringClassic() {
  return (
    (typeof inpaMode === 'function' && inpaMode()) ||
    (typeof inpaTheme === 'function' && inpaTheme())
  );
}

/** WDS's series names: the model line before the chassis code. */
const WDS_SERIES = {
  E38: '7',
  E39: '5',
  E46: '3',
  E52: 'Z8',
  E53: 'X5',
  E60: '5',
  E63: '6',
  E65: '7',
  E70: 'X5',
  E71: 'X6',
  E83: 'X3',
  E85: 'Z4',
  E87: '1',
  E89: 'Z4',
  E90: '3',
  F01: '7',
};

/**
 * A side-on saloon in WDS's grey, standing in for the series photo when
 * there is none (WDS's pictures are not part of this build).
 * @returns {string} SVG markup
 */
function wiringCarSilhouette() {
  return `<svg class="wds-car-svg" viewBox="0 0 160 70" aria-hidden="true">
    <path d="M8 48 L12 36 Q16 31 26 30 L48 28 Q60 16 76 14 L104 14 Q118 15 130 27 L146 30 Q154 32 154 40 L154 48 Z"
          fill="#c9ccd2" stroke="#5a5f68" stroke-width="1.5"/>
    <path d="M56 28 Q66 18 78 17 L100 17 Q112 18 120 28 Z" fill="#8fa3bd" stroke="#5a5f68" stroke-width="1"/>
    <line x1="88" y1="17" x2="88" y2="28" stroke="#5a5f68" stroke-width="1.5"/>
    <circle cx="40" cy="49" r="11" fill="#2b2e33"/><circle cx="40" cy="49" r="5" fill="#9aa0a8"/>
    <circle cx="124" cy="49" r="11" fill="#2b2e33"/><circle cx="124" cy="49" r="5" fill="#9aa0a8"/>
  </svg>`;
}

/**
 * One series on WDS's selection page: the caption bar ("3  E46") over its
 * picture. A photo at img/wds-series/<chassis>.jpg is used when the build
 * carries one; otherwise the drawn car stands in.
 * @param {string} id - chassis code
 * @returns {HTMLButtonElement}
 */
function wiringSeriesTile(id) {
  const tile = document.createElement('button');
  tile.type = 'button';
  tile.className = 'wds-car';
  const series = WDS_SERIES[id] || '';
  tile.innerHTML =
    `<span class="wds-car-cap">${esc(series)}&nbsp;&nbsp;${esc(dispChassis(id))}</span>` +
    `<span class="wds-car-pic">${wiringCarSilhouette()}</span>`;
  const img = new Image();
  img.alt = '';
  img.onload = () => {
    const pic = tile.querySelector('.wds-car-pic');
    pic.innerHTML = '';
    pic.appendChild(img);
  };
  img.src = `img/wds-series/${encodeURIComponent(id)}.jpg`;
  tile.onclick = () => showWiring(id);
  return tile;
}

/**
 * WDS's series-selection page: its toolbar and blue title bar (the same
 * chrome the diagram screen wears), the "Series selection" bar, and the
 * white page the tiles go on.
 * @returns {string}
 */
function wiringSeriesFrameHtml() {
  return `
    <div class="wds-series">
      <div class="wds-toolbar">
        <button class="wds-btn" id="wds-sel-print" title="Print this page">Print</button>
        <button class="wds-btn" id="wds-sel-exit" title="Leave wiring and return home">Exit</button>
      </div>
      <div class="wds-titlebar">
        <span>WDS BMW Wiring Diagram System - English</span>
        <span class="wds-version">Version 5.0</span>
      </div>
      <div class="wds-sectionbar">Series selection</div>
      <div class="wds-series-body">
        <div class="wds-series-head">
          <span>Select series</span>
        </div>
      </div>
    </div>`;
}

/**
 * The picker's Back key: out to the Apps hub.
 * @returns {{key: string, keyLabel: string, label: string, kind: string, fn: () => void}}
 */
function wiringPickerBackAction() {
  return {
    key: 'Escape',
    keyLabel: 'Esc',
    label: 'Back',
    kind: 'back',
    fn: showApps,
  };
}

/**
 * The picker: a VIN entry card, then every car with diagrams.
 * @returns {Promise<void>}
 */
async function showWiringChassis() {
  lastScreen = showWiringChassis;
  setCrumbs([
    { label: 'Vehicles', fn: showChassis },
    { label: 'Apps', fn: showApps },
    { label: 'Wiring' },
  ]);
  // the reader may leave while this screen loads (screenOwner)
  const _mine = screenOwner();
  sbLeft.textContent = 'wiring';
  // no F-key bar on wiring, either layout (the diagram screen drops it too);
  // Esc and the number keys still work. setCrumbs restores it.
  document.body.classList.add('wds-nofkeys');
  setActions([wiringPickerBackAction()]);

  // WDS's own look in the classic layout (or under the INPA skin): its
  // series-selection page, picture tiles under WDS's toolbar and title bar
  const classic = wiringClassic();
  let host = view;
  if (classic) {
    view.innerHTML = wiringSeriesFrameHtml();
    host = view.querySelector('.wds-series-body');
    wiringOn(view, '#wds-sel-exit', showApps);
    wiringOn(view, '#wds-sel-print', () => window.print());
  } else {
    view.innerHTML = head(
      'WDS',
      'Wiring Diagrams',
      'BMW’s own schematics. Enter a VIN or pick a vehicle to browse its diagrams.'
    );
  }

  // VIN search: decode the VIN to a chassis (same index the Parts catalogue
  // uses) and open its wiring. A saved VIN is remembered and pre-filled, so a
  // returning user is one Enter away from their car.
  host.appendChild(buildWiringVinBox());

  const grid = document.createElement('div');
  grid.className = classic ? 'wds-series-grid' : 'chassis-grid stagger';

  // fill the page while the 21 probes run (several seconds on a hosted site)
  const wait = wiringLoadingEl('Looking for the vehicles with diagrams…');
  host.appendChild(wait);
  host.appendChild(grid);

  const ids = await wiringChassisList();
  wait.remove();
  if (!ids.length) {
    host.appendChild(wiringAbsentNote());
    return;
  }
  ids.forEach((id, i) =>
    grid.appendChild(
      classic ? wiringSeriesTile(id) : wiringChassisCard(id, i, false)
    )
  );
  if (!classic) stagger(grid, 22);
  if (!_mine()) return;
  sbRight.textContent = `${ids.length} chassis`;
  if (!_mine()) return;
  setActions([
    ...ids.slice(0, WIRING_PICKER_HOTKEYS).map((id, i) => ({
      key: String(i + 1),
      label: dispChassis(id),
      fn: () => showWiring(id),
    })),
    wiringPickerBackAction(),
  ]);
}


