/**
 * The bare ISTA document id a deep link names: openDoc looks like "d:<id>"
 * (the documents route) or is numeric; anything else is a WDS doc.
 * @param {string | null} openDoc - the doc argument of showWiring
 * @returns {string | null}
 */
function wiringDeepDocId(openDoc) {
  if (!openDoc) return null;
  if (/^d:/.test(openDoc)) return openDoc.slice(2);
  if (/^\d+$/.test(openDoc)) return openDoc;
  return null;
}

/**
 * Re-tie a persisted tab to a live entry: an ISTA document tab is
 * self-contained, a WDS doc must still exist in the index (a rebuilt archive
 * that dropped it just skips the tab), a glossary tab has no doc and is kept
 * as saved.
 * @param {WiringTabEntry} t - the saved tab
 * @param {WiringIndexEntry[]} index - the flat WDS index
 * @returns {WiringTabEntry | null}
 */
function wiringResolveSavedTab(t, index) {
  if (t.doc && String(t.doc).startsWith('d:'))
    return docsTabEntryById(String(t.doc).slice(2), t.name, t.kind);
  if (t.doc) return index.find((e) => e.doc === t.doc) || null;
  return { name: t.name, kind: t.kind };
}

/**
 * Keep the doc count (status bar + empty state) faithful to the mode: all
 * diagrams, or only those not off-build for the car.
 * @param {WiringViewCtx} ctx - the open view
 * @returns {void}
 */
function wiringRefreshCount(ctx) {
  const n = wiringCountShown(ctx.data.tree);
  const label =
    `${n} diagram${n === 1 ? '' : 's'}` +
    (wiringVinHit && wiringVinFilterOn ? ' for your car' : '');
  sbRight.textContent = label;
  const empty = ctx.viewEl.querySelector('.wiring-emptycount');
  if (empty) empty.textContent = label;
}

/**
 * Render whichever tree the active category calls for. Diagrams is the WDS
 * tree; Components and Repair render the ISTA document tree (loaded lazily)
 * filtered to their doc types. The tab workspace, VIN filter and search all
 * work across categories.
 * @param {WiringViewCtx} ctx - the open view
 * @returns {Promise<void>}
 */
async function wiringRenderCurrentTree(ctx) {
  const { catHost, searchEl, treeEl } = ctx;
  const openTab = (entry) => ctx.tabs.openTab(entry);
  catHost &&
    catHost
      .querySelectorAll('.wiring-cat')
      .forEach((b) => b.classList.toggle('active', b.dataset.cat === ctx.cat));
  searchEl.value = '';
  searchEl.dispatchEvent(new Event('input'));
  // clear the tree body but keep the VIN banner (first child) if present
  const banner = treeEl.querySelector('.wiring-vinbanner');
  treeEl.innerHTML = '';
  if (banner) treeEl.appendChild(banner);
  if (ctx.cat === 'diagrams') {
    wiringRenderTree(ctx.data.tree, treeEl, 0, openTab);
    ctx.refreshCount();
    return;
  }
  if (!ctx.docsData) {
    const wait = wiringLoadingEl('Loading documents…');
    treeEl.appendChild(wait);
    try {
      ctx.docsData = await loadDocs(ctx.chassisId);
    } catch (e) {
      wait.innerHTML = `<div class="wiring-empty">No documents shipped for ${esc(dispChassis(ctx.chassisId))}.</div>`;
      return;
    }
    wait.remove();
  }
  const pruned = docsPruneTree(
    ctx.docsData.tree,
    docsCategoryKeep(ctx.cat)
  ) || {
    name: '',
  };
  wiringRenderDocsTree(pruned, treeEl, 0, openTab);
  if (wiringVinHit) {
    const b = treeEl.querySelector('.wiring-vinbanner');
    if (b && b._applyFilter) b._applyFilter(wiringVinFilterOn);
  }
  const n = docsCount(pruned);
  sbRight.textContent = `${n} document${n === 1 ? '' : 's'}`;
}

/**
 * The category tabs (modern layout): switching re-renders the tree and
 * remembers the choice.
 * @param {WiringViewCtx} ctx - the open view
 * @returns {void}
 */
function wiringBindCategories(ctx) {
  if (!ctx.catHost) return;
  ctx.catHost.querySelectorAll('.wiring-cat').forEach((btn) => {
    btn.onclick = () => {
      if (ctx.cat === btn.dataset.cat) return;
      ctx.cat = btn.dataset.cat;
      Settings.set('wiringCat', ctx.cat);
      wiringRenderCurrentTree(ctx);
    };
  });
}

/**
 * Search: flat results across the active category, tree hidden while typing.
 * @param {WiringViewCtx} ctx - the open view
 * @returns {void}
 */
function wiringBindSearch(ctx) {
  const { searchEl, treeEl } = ctx;
  let searchWrap = null;
  searchEl.oninput = () => {
    const q = searchEl.value.trim().toLowerCase();
    if (searchWrap) {
      searchWrap.remove();
      searchWrap = null;
    }
    treeEl.hidden = !!q;
    if (!q) return;
    const hits = wiringSearchHits(
      q,
      ctx.cat,
      ctx.index,
      ctx.docsData ? ctx.docsData.tree : null
    );
    searchWrap = wiringSearchResultsEl(hits, ctx.cat, (entry) =>
      ctx.tabs.openTab(entry)
    );
    treeEl.parentNode.appendChild(searchWrap);
    sbRight.textContent = `${hits.length} match${hits.length === 1 ? '' : 'es'}`;
  };
}

/**
 * Prev/next step through documents in tree order (the flat index IS that
 * order), moving the active tab rather than opening one per step.
 * @param {WiringViewCtx} ctx - the open view
 * @param {number} d - +1 or -1
 * @returns {void}
 */
function wiringStep(ctx, d) {
  const index = ctx.index;
  if (!index.length) return;
  ctx.atIndex = (ctx.atIndex + d + index.length) % index.length;
  const entry = index[ctx.atIndex];
  const active = ctx.tabs.activeEntry();
  if (active && active.doc) ctx.tabs.replaceActive(entry);
  else ctx.tabs.openTab(entry);
}

/**
 * Open the first document: a deep-linked ISTA doc or WDS doc (ECU / shared
 * link), else the tab that was active when the user last left, else the
 * placeholder. A deep link becomes a tab too, on top of any restored ones.
 * @param {WiringViewCtx} ctx - the open view
 * @param {string | null} openDoc - the doc argument of showWiring
 * @param {string | null} deepDocId - the bare ISTA id when openDoc names one
 * @returns {void}
 */
function wiringOpenInitial(ctx, openDoc, deepDocId) {
  const { tabs, treeEl, data, index } = ctx;
  // openTab focuses an already-open tab, but focusTab short-circuits when
  // that tab is already the active one -- which it is right after a reload
  // that restored this same doc as the active tab, so nothing would draw.
  // Render it explicitly in that case; otherwise open/focus as normal.
  const openOrRedraw = (entry) => {
    if (tabs.isActive(entry) && tabs.has(entry)) tabs.renderActive();
    else tabs.openTab(entry);
  };
  if (deepDocId) {
    const entry = docsTabEntryById(deepDocId, 'Document', '');
    // recover its title/type from the loaded docs tree if available
    const d = ctx.docsData ? docsFindById(ctx.docsData.tree, deepDocId) : null;
    if (d) {
      entry.name = d.title;
      entry.kind = d.type;
    }
    openOrRedraw(entry);
  } else if (openDoc) {
    const hit =
      index.find((e) => e.doc === openDoc) ||
      index.find((e) => e.name === openDoc);
    if (hit) {
      openOrRedraw(hit);
      wiringExpandTreeToDoc(treeEl, data.tree, hit.doc);
    } else if (tabs.active) {
      tabs.renderActive();
    } else wiringRenderPlaceholder(ctx);
  } else if (tabs.active) {
    // reopen the tab that was active when the user last left
    tabs.renderActive();
    const act = tabs.open.find((t) => t.doc && wiringTabKey(t) === tabs.active);
    if (act) wiringExpandTreeToDoc(treeEl, data.tree, act.doc);
  } else {
    wiringRenderPlaceholder(ctx);
  }
}

/**
 * Fill the mounted frame once the archive (and, with a VIN, the
 * applicability index) is in: tabs, prev/next, the VIN banner, categories,
 * the tree, search, the restored workspace and the first document.
 * @param {WiringViewCtx} ctx - the open view, with data and index set
 * @param {string | null} openDoc - the doc argument of showWiring
 * @returns {void}
 */
function wiringPopulate(ctx, openDoc) {
  const { split, treeEl, data } = ctx;
  ctx.tabs = new WiringTabStrip(
    split.querySelector('#wiring-tabs'),
    ctx.chassisId,
    {
      render: (entry) => wiringRenderEntry(ctx, entry),
      empty: () => wiringRenderPlaceholder(ctx),
    }
  );
  const openTab = (entry) => ctx.tabs.openTab(entry);
  wiringOn(split, '#wds-prev', () => wiringStep(ctx, -1));
  wiringOn(split, '#wds-next', () => wiringStep(ctx, 1));

  treeEl.innerHTML = ''; // drop the "loading" placeholder
  ctx.refreshCount = () => wiringRefreshCount(ctx);
  if (wiringVinHit) {
    // applied after the tree renders below (folders must exist first)
    treeEl.appendChild(
      buildWiringVinBanner(wiringVinHit, ctx.body, ctx.refreshCount)
    );
  }
  wiringBindCategories(ctx);

  // A deep-linked ISTA doc forces a document category; otherwise honour the
  // remembered/param category.
  const deepDocId = wiringDeepDocId(openDoc);
  if (ctx.cat === 'diagrams' && !deepDocId) {
    wiringRenderTree(data.tree, treeEl, 0, openTab);
    // now that the tree exists, apply the default VIN filter (folders present)
    if (wiringVinHit) {
      const banner = treeEl.querySelector('.wiring-vinbanner');
      banner && banner._applyFilter(true);
    }
    ctx.refreshCount();
  } else {
    // a doc category (or a deep-linked doc): render that tree instead
    if (deepDocId && ctx.cat === 'diagrams') ctx.cat = 'repair';
    wiringRenderCurrentTree(ctx);
  }
  wiringBindSearch(ctx);

  // restore the persisted tab workspace for this chassis
  ctx.tabs.restore(wiringTabsLoad(ctx.chassisId), (t) =>
    wiringResolveSavedTab(t, ctx.index)
  );
  wiringOpenInitial(ctx, openDoc, deepDocId);
}

/**
 * The Wiring & Documents screen for one car. `vin` (a decoded VIN hit) turns
 * on ISTA-style applicability filtering: each diagram is tagged match / off
 * / neutral against the vehicle, and a toggle can hide the off ones. Null =
 * no filtering. `openDoc` opens straight to a document (an SP doc id or
 * name, "d:<id>" or a bare numeric ISTA id); `category` picks the tree
 * (remembered otherwise; a deep-linked doc picks its own).
 * @param {string} chassisId - chassis code
 * @param {string | null} [openDoc] - document to open first
 * @param {WiringVinHit | null} [vin] - decoded VIN to filter against
 * @param {WiringCategory | null} [category] - tree to show
 * @returns {void}
 */
function showWiring(chassisId, openDoc = null, vin = null, category = null) {
  lastScreen = () => showWiring(chassisId, null, vin);
  wiringVinHit = vin || null; // module-level so the tree and search can read it
  setCrumbs([
    { label: 'Vehicles', fn: showChassis },
    { label: 'Apps', fn: showApps },
    { label: 'Wiring & Documents', fn: showWiringChassis },
    { label: dispChassis(chassisId) },
  ]);
  // the filtered vehicle rides in the URL, so a reload keeps the filter
  if (!openDoc && typeof routeSetFiltered === 'function')
    routeSetFiltered('wiring', chassisId, vin && vin.vin);
  sbLeft.textContent = 'loading…';
  // no page heading: a schematic wants every pixel of height, crumbs say where
  // you are
  view.innerHTML = '';

  // WDS's own chrome in the classic layout or under the INPA skin
  const classic = wiringClassic();
  // no F-key bar either mode: both layouts carry Back/print/help on their own
  // chrome, and the bar would cost the diagram 52px. setCrumbs restores it.
  document.body.classList.add('wds-nofkeys');
  const split = document.createElement('div');
  split.className = 'split wiring-split' + (classic ? ' wds-frame' : '');
  split.innerHTML = wiringFrameHtml(chassisId, classic);
  view.appendChild(split);

  const treeEl = split.querySelector('#wiring-tree');
  // the archive is 2-24 MB: real wait before the tree appears, so fill it
  treeEl.appendChild(
    wiringLoadingEl(`Loading ${dispChassis(chassisId)} diagrams…`)
  );
  const viewEl = split.querySelector('#wiring-view');
  const searchEl = split.querySelector('#wiring-search');
  const body = split.querySelector('.wiring-body');

  wiringOn(split, '#wds-series', showWiringChassis);
  wiringOn(split, '#wds-exit', showChassis);
  wiringOn(split, '#wds-back', showWiringChassis);
  wiringOn(split, '#wds-start', () => showWiring(chassisId));
  wiringOn(split, '#wds-help', () => showWiringHelp(chassisId));
  wiringOn(split, '#wds-print', () => printWiring(chassisId));
  wiringOn(split, '#wds-new', () => {
    searchEl.value = '';
    searchEl.dispatchEvent(new Event('input'));
  });
  wiringOn(split, '#wds-find', () =>
    searchEl.dispatchEvent(new Event('input'))
  );

  const setPane = (mode, remember = true) =>
    wiringSetPane(split, mode, remember);
  wiringOn(split, '#wds-pane-doc', () => setPane('doc'));
  wiringOn(split, '#wds-pane-split', () => setPane('split'));
  wiringOn(split, '#wds-pane-tree', () => setPane('tree'));
  // opened via a VIN: the point is the FILTERED TREE, so force it visible even
  // if the saved pref was diagram-only (don't overwrite that pref). Otherwise
  // honour the remembered pane.
  if (wiringVinHit) {
    const pref = Settings.get('wdsPane', 'split');
    setPane(pref === 'doc' ? 'split' : pref, false);
  } else {
    setPane(Settings.get('wdsPane', 'split'));
  }
  tipify(split);

  // Back from the tree leaves wiring; back from a DIAGRAM on a phone returns to
  // the tree first -- panes are exclusive there, so leaving would skip a level.
  const leaveWiring = () => {
    if (wiringIsPhone() && body.dataset.pane === 'doc') {
      setPane('tree', false);
      return;
    }
    showWiringChassis();
  };
  const browseActions = wiringBrowseActions(chassisId, leaveWiring);
  setActions(browseActions);

  /** @type {WiringViewCtx} */
  const ctx = {
    chassisId,
    classic,
    split,
    body,
    treeEl,
    viewEl,
    searchEl,
    catHost: split.querySelector('#wiring-cats'),
    setPane,
    leaveWiring,
    browseActions,
    data: null,
    index: [],
    tabs: null,
    docsData: null, // the .docs bundle, loaded on first non-diagram use
    cat: category || Settings.get('wiringCat', WIRING_DEFAULT_CATEGORY),
    atIndex: -1,
    refreshCount: () => {},
  };

  // load the archive and (when filtering by VIN) BMW's applicability index in
  // parallel, so leaves can be tagged the moment the tree renders
  Promise.all([
    loadWiring(chassisId),
    wiringVinHit && typeof wiringApplicability !== 'undefined'
      ? wiringApplicability.load(wiringVinHit).catch(() => null)
      : Promise.resolve(),
  ])
    .then(([data]) => {
      ctx.data = data;
      ctx.index = wiringIndex(data.tree);
      sbLeft.textContent = 'wiring';
      // sbRight is set by refreshCount so it stays faithful to the mode
      wiringPopulate(ctx, openDoc);
    })
    .catch((e) => {
      viewEl.innerHTML = errorBlock(e.message);
      sbLeft.textContent = 'no wiring data';
    });
}

/**
 * WDS's own Help page, with our controls (a wheel and a drag, not Strg+click).
 * @param {string} chassisId - chassis code, to return to its tree
 * @returns {void}
 */
function showWiringHelp(chassisId) {
  setCrumbs([
    { label: 'Vehicles', fn: showChassis },
    { label: 'Wiring', fn: showWiringChassis },
    { label: dispChassis(chassisId), fn: () => showWiring(chassisId) },
    { label: 'Help' },
  ]);
  view.innerHTML = head('WDS', 'Operation and navigation', '');
  const art = document.createElement('article');
  art.className = 'wiring-doc wds-help-doc';
  art.innerHTML = `
    <h2>Navigation</h2>
    <ul>
      <li>Click a folder in the tree to open it, click again to close it.</li>
      <li><strong>New</strong> clears the search and returns to the full tree.</li>
      <li><strong>&lt;&lt;</strong> and <strong>&gt;&gt;</strong> step through the
          documents in tree order.</li>
    </ul>
    <h2>Search</h2>
    <ul>
      <li>Type in the field at the bottom left; results replace the tree as
          you type, and <strong>Search</strong> repeats the current word.</li>
      <li>Every document title in this vehicle is searched at once.</li>
    </ul>
    <h2>Zooming and moving a diagram</h2>
    <ul>
      <li>Scroll the wheel over a diagram to zoom about the pointer.</li>
      <li>Drag with the mouse to move it.</li>
      <li>The footer buttons and the keys <strong>+</strong>,
          <strong>-</strong> and <strong>0</strong> (fit) do the same.</li>
      <li>Diagrams are vector, so they stay sharp at any magnification.</li>
    </ul>
    <h2>What the marks in the tree mean</h2>
    <ul>
      <li><span class="wiring-dot" style="background:var(--amber)"></span>
          wiring diagram &nbsp;
          <span class="wiring-dot" style="background:var(--green)"></span>
          component location &nbsp;
          <span class="wiring-dot" style="background:#6ab0ff"></span>
          connector view</li>
      <li><span class="wiring-dot" style="background:#b98cff;border-radius:50%"></span>
          pin assignment &nbsp;
          <span class="wiring-dot" style="background:#ffd166;border-radius:50%"></span>
          specification values &nbsp;
          <span class="wiring-dot" style="background:var(--red)"></span>
          test procedure</li>
    </ul>
    <p>The diagrams, their titles and their arrangement are BMW's own, taken
       from WDS. Printing uses the browser's print dialog.</p>`;
  view.appendChild(art);
  setActions([
    {
      key: 'Escape',
      keyLabel: 'Esc',
      label: 'Back',
      kind: 'back',
      fn: () => showWiring(chassisId),
    },
  ]);
}


;/* ==== screens/etk/data.js ==== */
/**
 * @file Parts catalogue data access: locating and streaming the per-chassis
 * .etk bundles, the vehicle attribute tree, the car photos, and turning an
 * archived image into something an <img> can show.
 *
 * tools/etk_import.py packs one .etk archive per car: tree.json (assembly
 * groups -> diagrams -> parts) plus the exploded-view images (jpg/png). Same
 * archive shape and loading path as the .wiring bundles -- fflate inflates,
 * and the offline export inlines base64.
 *
 * The .etk bundles are 6.4 GB across 246 cars -- too big to ship in the Pages
 * repo. They live in a Hugging Face dataset and stream in at runtime (HF's
 * resolve URLs reflect the request Origin, so cross-origin fetch from
 * bmweb.danner.ink is CORS-clean -- verified). Local data/etk/ wins when
 * present (dev + the offline single-file export), else fall back to HF.
 */

/* exported ETK_HF_BASE, etkFetch, etkDataUrl, etkFetchFirst, loadEtk, readWithProgress, etkChassisList, loadVehicles, loadEtkThumbs, etkThumbUrl, etkImageUrl, loadEtkHotspots, loadEtkLines */

/**
 * One part row on a diagram.
 * @typedef {object} EtkPart
 * @property {string} pos - position number on the exploded view
 * @property {string} sachnr - the 7-digit part number
 * @property {string} [pre] - 4-digit main-group + subgroup prefix that makes the full 11-digit number
 * @property {string} name - part description
 * @property {number[]} [fit] - indices into EtkTree.variants this part fits; absent means it fits every variant
 */

/**
 * One exploded-view diagram (a Bildtafel) with its parts list.
 * @typedef {object} EtkDiagram
 * @property {string} btnr - diagram number, the deep-link id (#apps/parts/E46/11/11_0100)
 * @property {string} name - diagram title
 * @property {string} [img] - image file name under img/ in the archive
 * @property {EtkPart[]} parts - parts drawn on the diagram
 */

/**
 * A function group inside a main group: a named list of diagrams.
 * @typedef {object} EtkGroup
 * @property {string} name - group title
 * @property {EtkDiagram[]} diagrams - diagrams under this group
 */

/**
 * A main group (Hauptgruppe) as drawn on the chassis landing grid.
 * @typedef {object} EtkMainGroup
 * @property {string} hg - two-digit main-group number ("11" = engine)
 * @property {string} name - main-group title
 * @property {string} [icon] - icon image ref under img/ in the archive
 * @property {EtkGroup[]} groups - function groups under this main group
 */

/**
 * One exact vehicle the catalogue can be filtered to.
 * @typedef {object} EtkVariant
 * @property {string} [model] - model name ("325i")
 * @property {string} [body] - body code (Lim, Tou, Cou, Cab...)
 * @property {string} [motor] - engine code ("M54")
 * @property {string} [steer] - 'L' or 'R'
 * @property {string} [gear] - 'A' automatic, 'M' manual, 'N' not split by transmission
 * @property {string|number} [date] - introduction date as YYYYMMDD
 */

/**
 * The parsed tree.json of one chassis archive.
 * @typedef {object} EtkTree
 * @property {string} chassis - chassis code the archive was packed for
 * @property {EtkMainGroup[]} [maingroups] - main groups in catalogue order
 * @property {EtkVariant[]} [variants] - the vehicles parts can be filtered to
 */

/**
 * A loaded chassis archive: its tree plus the raw files (images) inside it.
 * @typedef {object} EtkBundle
 * @property {EtkTree} tree - the parsed catalogue tree
 * @property {Map<string, Uint8Array>} files - archive entries by path ("img/319345.jpg")
 */

/**
 * One clickable callout rectangle on an exploded view: the callout number,
 * then its box in the diagram image's OWN pixel space (top-left origin).
 * @typedef {[string, number, number, number, number]} EtkHotspot
 */

/**
 * The parsed <CHASSIS>.hs.json.gz: which rectangles each diagram carries.
 * @typedef {object} EtkHotspotFile
 * @property {number} v - format version (1)
 * @property {Record<string, EtkHotspot[]>} bt - btnr -> its rectangles
 */

/**
 * Download progress callback. `total` is 0 when the server sent no
 * Content-Length, in which case the caller shows an indeterminate bar.
 * @typedef {(loaded: number, total: number) => void} EtkProgressFn
 */

/**
 * One row of vehicles.json: [steer, gear, introduction date YYYYMMDD, mospid].
 * @typedef {[string, string, string, string]} EtkVehicleRow
 */

/**
 * vehicles.json: chassis -> body -> model -> variant rows.
 * @typedef {Record<string, Record<string, Record<string, EtkVehicleRow[]>>>} EtkVehicleTree
 */

/** @type {Map<string, EtkBundle>} loaded archives by upper-cased chassis id */
const ETK_CACHE = new Map();

/** @type {string[]|null} memoised list of chassis ids that have an archive */
let etkChassisIds = null;

/** Where the ETK data lives when there is no local copy. */
const ETK_HF_BASE =
  'https://huggingface.co/datasets/CraigFf/bmweb-etk/resolve/main/';

/** Path under the local web root where a build may ship the ETK data. */
const ETK_LOCAL_DIR = '/data/etk/';

/**
 * The fetch to use for ETK data: the un-shimmed one when the web shim has
 * wrapped window.fetch, else the browser's own.
 * @returns {typeof fetch}
 */
function etkFetch() {
  return typeof webRealFetch === 'function'
    ? webRealFetch
    : window.fetch.bind(window);
}

/**
 * URL of one ETK data file, from the local build tree or the hosted dataset.
 * @param {string} rel - path relative to the ETK data root ("E46.etk", "thumbs/thumbs.json")
 * @param {boolean} local - true for the local copy, false for the hosted one
 * @returns {string}
 */
function etkDataUrl(rel, local) {
  if (local) {
    const base = typeof WEB_BASE === 'string' ? WEB_BASE : '';
    return `${base}${ETK_LOCAL_DIR}${rel}`;
  }
  return `${ETK_HF_BASE}${rel}`;
}

/**
 * Fetch one ETK data file, local copy first, then the hosted dataset. Network
 * errors on either count as a miss.
 * @param {string} rel - path relative to the ETK data root
 * @returns {Promise<{ resp: Response, url: string }|null>} the first OK response, or null when neither answered
 */
async function etkFetchFirst(rel) {
  const real = etkFetch();
  for (const local of [true, false]) {
    const url = etkDataUrl(rel, local);
    const resp = await real(url).catch(() => null);
    if (resp && resp.ok) return { resp, url };
  }
  return null;
}

/**
 * Load (and cache) the parts archive of one chassis. An inline base64 copy
 * (the offline single-file export's BMWEB_ETK) wins over any fetch.
 * @param {string} chassisId - chassis code, any case
 * @param {EtkProgressFn} [onProgress] - called as the bundle downloads
 * @returns {Promise<EtkBundle>}
 * @throws {Error} when no copy of the archive can be found
 */
async function loadEtk(chassisId, onProgress) {
  const id = chassisId.toUpperCase();
  if (ETK_CACHE.has(id)) return ETK_CACHE.get(id);
  let bytes;
  const inline =
    typeof BMWEB_ETK === 'object' && BMWEB_ETK ? BMWEB_ETK[id] : null;
  if (inline) {
    const bin = atob(inline);
    bytes = new Uint8Array(bin.length);
    for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  } else {
    const hit = await etkFetchFirst(`${id}.etk`);
    if (!hit) throw new Error(`no parts data for ${dispChassis(id)}`);
    bytes = await readWithProgress(hit.resp, onProgress);
  }
  const unzipped = fflate.unzipSync(bytes);
  const tree = JSON.parse(new TextDecoder().decode(unzipped['tree.json']));
  const files = new Map(Object.entries(unzipped));
  // THE LINES' VALIDITY RIDES BESIDE THE PUBLISHED BUNDLE (dates, steering,
  // condition, note -- see lines.js); a bundle built with them inline needs
  // nothing from the sidecar, and a chassis without one browses as before
  if (typeof etkMergeLines === 'function') {
    const side = await loadEtkLines(id);
    if (side) etkMergeLines(tree, side);
  }
  const data = { tree, files };
  ETK_CACHE.set(id, data);
  return data;
}

/** @type {Map<string, Promise<object|null>>} chassis id -> its lines file */
const ETK_LINES_CACHE = new Map();

/**
 * Load (and cache) one chassis's parts-line validity file. Never throws: a
 * chassis whose file is missing or unreadable resolves to null and its
 * parts carry no conditions.
 * @param {string} chassisId - chassis code, any case
 * @returns {Promise<object|null>} the parsed <CHASSIS>.lines.json.gz, or null
 */
function loadEtkLines(chassisId) {
  const id = String(chassisId || '').toUpperCase();
  if (ETK_LINES_CACHE.has(id)) return ETK_LINES_CACHE.get(id);
  const p = (async () => {
    const hit = await etkFetchFirst(`${id}.lines.json.gz`);
    if (!hit) return null;
    try {
      const bytes = new Uint8Array(await hit.resp.arrayBuffer());
      const data = JSON.parse(fflate.strFromU8(fflate.gunzipSync(bytes)));
      return data && data.ln ? data : null;
    } catch (e) {
      return null;
    }
  })();
  ETK_LINES_CACHE.set(id, p);
  return p;
}

/** @type {Map<string, Promise<EtkHotspotFile|null>>} chassis id -> its hotspot file, in flight or settled */
const ETK_HS_CACHE = new Map();

/**
 * Load (and cache) one chassis's callout rectangles. This rides BESIDE the
 * bundle rather than inside it: the .etk archives are already published and
 * re-uploading all of them to add a few KB of rectangles is not worth it.
 *
 * Never throws and never blocks the diagram: a chassis whose file has not
 * been generated (or that cannot be reached) resolves to null, and the viewer
 * simply draws the plain, non-interactive exploded view.
 * @param {string} chassisId - chassis code, any case
 * @returns {Promise<EtkHotspotFile|null>} the parsed file, or null when there is none
 */
function loadEtkHotspots(chassisId) {
  const id = String(chassisId || '').toUpperCase();
  if (ETK_HS_CACHE.has(id)) return ETK_HS_CACHE.get(id);
  const p = (async () => {
    const hit = await etkFetchFirst(`${id}.hs.json.gz`);
    if (!hit) return null;
    try {
      const bytes = new Uint8Array(await hit.resp.arrayBuffer());
      // same gunzip path as the VIN index -- fflate, already loaded for the
      // bundles, so no new dependency and it works in the offline export too
      const json = fflate.strFromU8(fflate.gunzipSync(bytes));
      const data = JSON.parse(json);
      return data && data.bt ? data : null;
    } catch (e) {
      // a truncated or half-written file must not take the diagram down with
      // it: the callouts are an enhancement, the drawing is the feature
      return null;
    }
  })();
  ETK_HS_CACHE.set(id, p);
  return p;
}

/**
 * Stream a fetch Response into a Uint8Array, reporting progress as chunks
 * arrive. Falls back to arrayBuffer() when the body isn't a readable stream
 * or nobody is listening for progress.
 * @param {Response} resp - the response to drain
 * @param {EtkProgressFn} [onProgress] - progress callback
 * @returns {Promise<Uint8Array>}
 */
async function readWithProgress(resp, onProgress) {
  const total = Number(resp.headers.get('content-length')) || 0;
  if (!resp.body || !resp.body.getReader || !onProgress) {
    const buf = new Uint8Array(await resp.arrayBuffer());
    if (onProgress) onProgress(buf.length, buf.length);
    return buf;
  }
  const reader = resp.body.getReader();
  const chunks = [];
  let loaded = 0;
  for (;;) {
    const { done, value } = await reader.read();
    if (done) break;
    chunks.push(value);
    loaded += value.length;
    onProgress(loaded, total);
  }
  const out = new Uint8Array(loaded);
  let off = 0;
  for (const c of chunks) {
    out.set(c, off);
    off += c.length;
  }
  return out;
}

/**
 * Every chassis that has a parts archive, sorted. One index.json lists them --
 * read it instead of HEAD-probing all ~135 cars (that would be hundreds of
 * requests to the hosted dataset). Memoised for the session.
 * @returns {Promise<string[]>}
 */
async function etkChassisList() {
  if (etkChassisIds) return etkChassisIds;
  if (typeof BMWEB_ETK === 'object' && BMWEB_ETK) {
    etkChassisIds = Object.keys(BMWEB_ETK).sort();
    return etkChassisIds;
  }
  const real = etkFetch();
  const tryIndex = async (local) => {
    try {
      const r = await real(etkDataUrl('index.json', local));
      return r.ok ? await r.json() : null;
    } catch (e) {
      return null;
    }
  };
  const idx = (await tryIndex(true)) || (await tryIndex(false));
  etkChassisIds = Array.isArray(idx) ? idx.slice().sort() : [];
  return etkChassisIds;
}

// ---- vehicle attribute tree (the ETK-style drill-down) --------------------
// vehicles.json: chassis -> body -> model -> [[steer,gear,year,mospid], ...].
// Small (~200 KB), ships in the repo (local), with an HF fallback.

/** @type {EtkVehicleTree|null} */
let etkVehicles = null;

/**
 * Load (and cache) vehicles.json, the attribute tree behind the identify-by-
 * attributes selector.
 * @returns {Promise<EtkVehicleTree>}
 * @throws {Error} when neither copy is reachable
 */
async function loadVehicles() {
  if (etkVehicles) return etkVehicles;
  const hit = await etkFetchFirst('vehicles.json');
  if (!hit) throw new Error('vehicle data not available');
  etkVehicles = await hit.resp.json();
  return etkVehicles;
}

// thumbs.json: which <chassis>_<body> car photos shipped (ETK's Vehicle
// Identification images, extracted from w_baureihe_kar_thb). Local first,
// then the Hugging Face dataset (where the rest of the ETK data lives).
// Non-fatal: the drill-down just keeps its silhouette if the set isn't there.

/** @type {Record<string, string>|null} "<chassis>_<body>" -> photo file name */
let etkThumbs = null;

/** The directory URL thumbs.json resolved from, so photos load beside it. */
let etkThumbsBase = '';

/**
 * Load (and cache) the car-photo index. Never throws: a missing set resolves
 * to an empty map.
 * @returns {Promise<Record<string, string>>}
 */
async function loadEtkThumbs() {
  if (etkThumbs) return etkThumbs;
  const hit = await etkFetchFirst('thumbs/thumbs.json');
  if (hit) {
    etkThumbs = await hit.resp.json();
    etkThumbsBase = hit.url.replace(/thumbs\.json$/, '');
    return etkThumbs;
  }
  etkThumbs = {};
  return etkThumbs;
}

/**
 * URL of the car photo for a chassis + body, if one shipped and the index has
 * loaded.
 * @param {string|null} chassis - chassis code
 * @param {string|null} body - body code
 * @returns {string|null}
 */
function etkThumbUrl(chassis, body) {
  const name =
    etkThumbs && chassis && body ? etkThumbs[`${chassis}_${body}`] : null;
  return name ? `${etkThumbsBase}${name}` : null;
}

/** @type {Map<string, string>} "<chassis>/<ref>" -> object URL, so each image is materialised once */
const ETK_IMG_URLS = new Map();

/**
 * An image ref in the tree ("319345.jpg") as a blob URL an <img> can show.
 * @param {EtkBundle} data - the loaded archive
 * @param {string|undefined} ref - image file name under img/
 * @returns {string|null} the object URL, or null when the ref is empty or missing from the archive
 */
function etkImageUrl(data, ref) {
  if (!ref) return null;
  const key = data.tree.chassis + '/' + ref;
  if (ETK_IMG_URLS.has(key)) return ETK_IMG_URLS.get(key);
  const bytes = data.files.get(`img/${ref}`);
  if (!bytes) return null;
  const ext = ref.split('.').pop().toLowerCase();
  const mime = ext === 'png' ? 'image/png' : 'image/jpeg';
  const url = URL.createObjectURL(new Blob([bytes], { type: mime }));
  ETK_IMG_URLS.set(key, url);
  return url;
}


;/* ==== screens/etk/labels.js ==== */
/**
 * @file Human-readable labels for the catalogue's coded attributes: body and
 * steering codes, gearboxes, introduction dates, the one-line variant caption,
 * and BMW's grouped 11-digit part-number layout.
 */

/* exported bodyLabel, etkSteerAbbrev, etkSteerLabel, etkGearLabel, etkYearMonth, etkVariantLabel, fmtSachnr, etkCarLabel */

/** Body code -> readable (Lim = Sedan, Tou = Touring, Cou = Coupé, Cab = Convertible...). */
const ETK_BODY_LABELS = {
  Lim: 'Sedan',
  Tou: 'Touring',
  Cou: 'Coupé',
  Cab: 'Convertible',
  com: 'Compact',
  Cabrio: 'Convertible',
};

/** Steering code -> the short form used in captions. */
const ETK_STEER_ABBREV = { L: 'LHD', R: 'RHD' };

/** Steering code -> the long form used in the attribute selector. */
const ETK_STEER_LABELS = { L: 'Left-hand drive', R: 'Right-hand drive' };

// ETK stores gearbox N = "Neutral" on chassis whose catalogue isn't split by
// transmission (the terminal shows "Neutral" there too, not a blank).
/** Gearbox code -> the long form used in the attribute selector. */
const ETK_GEAR_LABELS = { A: 'Automatic', M: 'Manual', N: 'Neutral' };

/** Gearbox code -> the short form used in the variant caption ('' = omit). */
const ETK_GEAR_ABBREV = { A: 'auto', M: 'man.', N: '' };

/** Length of a full YYYYMMDD date in the variant records. */
const ETK_DATE_LEN = 8;

/**
 * Readable body style for a body code; unknown codes pass through.
 * @param {string|undefined} b - body code (Lim, Tou, Cou, Cab, com, Cabrio...)
 * @returns {string}
 */
function bodyLabel(b) {
  return ETK_BODY_LABELS[b] || b || '';
}

/**
 * Short steering caption: LHD / RHD, '' for anything else.
 * @param {string|undefined} steer - 'L' or 'R'
 * @returns {string}
 */
function etkSteerAbbrev(steer) {
  return ETK_STEER_ABBREV[steer] || '';
}

/**
 * Long steering caption; unknown codes pass through.
 * @param {string} steer - 'L' or 'R'
 * @returns {string}
 */
function etkSteerLabel(steer) {
  return ETK_STEER_LABELS[steer] || steer;
}

/**
 * Long gearbox caption; unknown codes pass through, a blank reads "Neutral".
 * @param {string|undefined} gear - 'A', 'M' or 'N'
 * @returns {string}
 */
function etkGearLabel(gear) {
  return ETK_GEAR_LABELS[gear] || gear || 'Neutral';
}

/**
 * "MM/YYYY" from the front of a YYYYMMDD (or longer) date string.
 * @param {string} d - date digits
 * @returns {string}
 */
function etkYearMonth(d) {
  // month/year, not year-month: "2004-09" was read as a 2004 to 2009 range
  return `${d.slice(4, 6)}/${d.slice(0, 4)}`;
}

/**
 * One-line caption for a catalogue variant: "325i · Lim · M54 · LHD · man. · 09/2001".
 * @param {EtkVariant} v - the variant record
 * @returns {string}
 */
function etkVariantLabel(v) {
  const parts = [];
  if (v.model) parts.push(v.model);
  if (v.body) parts.push(v.body);
  if (v.motor) parts.push(v.motor);
  if (v.steer) parts.push(ETK_STEER_ABBREV[v.steer] || v.steer);
  if (v.gear) {
    const g = ETK_GEAR_ABBREV[v.gear];
    if (g) parts.push(g);
  }
  if (v.date) {
    const d = String(v.date);
    if (d.length === ETK_DATE_LEN) parts.push(etkYearMonth(d));
  }
  return parts.join(' · ');
}

/**
 * The caption for the CAR the catalogue is filtered to, when a VIN said
 * when it was built: the variant's model, body, engine, side and gearbox,
 * then "built 09/2004" -- the car's own month, not the month its type key
 * was introduced. The variant label's date is the introduction ("10/2001"
 * for an ET37), and printed beside a 2004 car it read as the car's year.
 * @param {EtkVariant} v - the matched variant
 * @param {{prod?: string|number}|null} [hit] - the decoded VIN
 * @returns {string}
 */
function etkCarLabel(v, hit) {
  const prod = String((hit && hit.prod) || '').slice(0, 6);
  if (!/^\d{6}$/.test(prod)) return etkVariantLabel(v);
  const parts = [];
  if (v.model) parts.push(v.model);
  if (v.body) parts.push(v.body);
  if (v.motor) parts.push(v.motor);
  if (v.steer) parts.push(ETK_STEER_ABBREV[v.steer] || v.steer);
  if (v.gear) {
    const g = ETK_GEAR_ABBREV[v.gear];
    if (g) parts.push(g);
  }
  parts.push(`built ${etkYearMonth(prod)}`);
  return parts.join(' · ');
}

/**
 * BMW part numbers print as the full 11-digit number when we have the group
 * prefix: main-group + subgroup + 7-digit sachnr, grouped "11 13 7 791 531".
 * Without a prefix, fall back to grouping the 7-digit number alone.
 * @param {string|number} s - the 7-digit part number
 * @param {string|number} [prefix] - the 4-digit main-group + subgroup prefix
 * @returns {string|number} the grouped number, or the input untouched when it isn't 7 digits
 */
function fmtSachnr(s, prefix) {
  const d = String(s).replace(/\D/g, '');
  if (prefix && d.length === 7) {
    const p = String(prefix).replace(/\D/g, '');
    if (p.length === 4) {
      // HG(2) UG(2) X(1) XXX(3) XXX(3)
      return `${p.slice(0, 2)} ${p.slice(2, 4)} ${d.slice(0, 1)} ${d.slice(1, 4)} ${d.slice(4)}`;
    }
  }
  if (d.length === 7) return `${d.slice(0, 2)} ${d.slice(2, 4)} ${d.slice(4)}`;
  return s;
}


;/* ==== screens/etk/select.js ==== */
/**
 * @file A styled dropdown that mimics the <select> interface the attribute
 * cascade uses: exposes .value (option index as string, '' for none),
 * .selectedIndex, .disabled, an .options-like list via setOptions(), and fires
 * 'change'. Keeps the cascade code unchanged while ditching the unstyleable
 * native list. The shared ui/dropdown.js deliberately does not cover this
 * contract (index-string .value, .selectedIndex, .onchange dual-fire, the
 * `_vals` sidecar the cascade hangs on it).
 */

/* exported makeSelect */

/**
 * The <select>-ish surface makeSelect() returns. Values are 0-based item
 * indices as strings ('' = none). selectedIndex mirrors native semantics
 * (0 = the placeholder, 1..N = items) so `sel.selectedIndex = 1` auto-picks
 * the first real item. The cascade hangs its own sidecars (`_vals`, `_vs`,
 * `_byYear`) on the element.
 * @typedef {HTMLDivElement & {
 *   value: string,
 *   disabled: boolean,
 *   selectedIndex: number,
 *   options: { textContent: string }[],
 *   setOptions: (items: string[], placeholder?: string|null) => void,
 *   setDisabledEmpty: () => void,
 *   openMenu: () => void,
 *   onchange: ((ev: Event) => void)|null,
 *   _vals?: string[],
 *   _vs?: EtkVehicleRow[],
 *   _byYear?: Record<string, string>|null,
 * }} EtkSelect
 */

/** Placeholder shown when a select has no explicit one. */
const ETK_SELECT_PLACEHOLDER = 'Select…';

/**
 * Build a styled single-choice dropdown with a <select>-like API.
 * @param {string} [placeholder] - text shown while nothing is picked
 * @returns {EtkSelect}
 */
function makeSelect(placeholder) {
  const root = /** @type {EtkSelect} */ (document.createElement('div'));
  root.className = 'etk-sel';
  const btn = document.createElement('button');
  btn.type = 'button';
  btn.className = 'etk-sel-btn';
  btn.innerHTML = `<span class="etk-sel-cur"></span><span class="etk-sel-caret">▾</span>`;
  const menu = document.createElement('div');
  menu.className = 'etk-sel-menu';
  menu.hidden = true;
  root.appendChild(btn);
  root.appendChild(menu);
  const cur = btn.querySelector('.etk-sel-cur');

  let items = []; // display strings
  let value = ''; // '' (placeholder) or a 0-based index string of an item
  let ph = placeholder || ETK_SELECT_PLACEHOLDER;
  let disabled = false;
  let outside = null;

  /** @returns {string} the caption for the current value */
  function label() {
    return value === '' ? ph : items[+value];
  }
  /** Repaint the button caption. */
  function paint() {
    cur.textContent = label();
    cur.classList.toggle('etk-sel-ph', value === '');
  }
  /** Rebuild the option rows. */
  function renderMenu() {
    menu.innerHTML = '';
    items.forEach((t, i) => {
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'etk-sel-opt' + (value === String(i) ? ' active' : '');
      b.textContent = t;
      b.onclick = (e) => {
        e.stopPropagation();
        value = String(i);
        paint();
        close();
        fire();
      };
      menu.appendChild(b);
    });
  }
  /** Open the menu (no-op when disabled or empty) and arm outside-click close. */
  function open() {
    if (disabled || !items.length) return;
    renderMenu();
    menu.hidden = false;
    root.classList.add('etk-sel-open');
    setTimeout(() => {
      outside = (e) => {
        if (!root.contains(e.target)) close();
      };
      document.addEventListener('click', outside);
    }, 0);
  }
  /** Close the menu and disarm outside-click close. */
  function close() {
    menu.hidden = true;
    root.classList.remove('etk-sel-open');
    if (outside) {
      document.removeEventListener('click', outside);
      outside = null;
    }
  }
  // fire both the event (for addEventListener) and the .onchange property the
  // cascade sets, since a div's onchange isn't auto-wired like a <select>'s.
  /** Notify listeners of a selection. */
  function fire() {
    root.dispatchEvent(new Event('change'));
    if (typeof root.onchange === 'function') root.onchange(new Event('change'));
  }

  btn.onclick = (e) => {
    e.stopPropagation();
    menu.hidden ? open() : close();
  };

  Object.defineProperties(root, {
    value: {
      get: () => value,
      set: (v) => {
        value = v === '' ? '' : String(v);
        paint();
      },
    },
    disabled: {
      get: () => disabled,
      set: (d) => {
        disabled = !!d;
        root.classList.toggle('etk-sel-disabled', disabled);
        if (d) close();
      },
    },
    selectedIndex: {
      get: () => (value === '' ? 0 : +value + 1),
      set: (i) => {
        value = i && i >= 1 ? String(i - 1) : '';
        paint();
      },
    },
    options: {
      get: () => [
        { textContent: ph },
        ...items.map((t) => ({ textContent: t })),
      ],
    },
  });
  // setOptions replaces the innerHTML-style population a native <select> gets
  root.setOptions = (arr, placeholderText) => {
    if (placeholderText != null) ph = placeholderText;
    items = arr.slice();
    value = '';
    paint();
    close();
  };
  root.setDisabledEmpty = () => {
    items = [];
    value = '';
    paint();
  };
  root.openMenu = () => open();
  paint();
  return root;
}


;/* ==== screens/etk/series.js ==== */
/**
 * @file Grouping vehicles.json's series codes the way ETK's Vehicle
 * Identification does: marketing series ("5'", "X3", "MINI") derived from
 * each chassis's model names, and a stable ordering within and across them.
 */

/* exported seriesSort, groupBySeries */

/**
 * Chassis codes bucketed by marketing series, in display order.
 * @typedef {object} EtkSeriesGroups
 * @property {string[]} order - series names in ETK's display order
 * @property {Record<string, string[]>} groups - series name -> sorted chassis codes
 */

/** Era rank of the leading letter of a car chassis code (E46 < F30 < G20...). */
const ETK_ERA_RANK = { E: 0, F: 1, G: 2, I: 3, U: 4 };

// Chassis whose model prefix is ambiguous, or which predate the numbering
// scheme, so their series can't be derived from the model names.
/** Hard overrides: chassis code -> marketing series. */
const ETK_SERIES_HARD = {
  E52: 'Z',
  E26: 'M',
  E72: 'X6',
  E169: 'Moto',
  E3: 'Classic',
  E9: 'Classic',
};

/** Display order of the series buckets (index = rank). */
const ETK_SERIES_ORDER = ['Z', 'M', 'i', 'MINI', 'Moto'];

/** Bucket rank for numbered series ("5'") and X series, which sort before the named ones. */
const ETK_SERIES_RANK_NUMBER = 0;
const ETK_SERIES_RANK_X = 1;
/** Named buckets start after number and X series. */
const ETK_SERIES_RANK_NAMED = 2;

// vehicles.json keys are BMW's internal ETK series codes. Most are the
// familiar chassis E-numbers (E46, F30, G20), but a tail of them are raw
// internal codes for motorcycles (K/R bikes), the classic '02 range and a few
// oddments (114, 2471, R56, MOSP...). Alphabetical sort buries the cars the
// user is actually after under those codes, so we bucket by kind: modern cars
// first (E/F/G/I/U + digits), then Minis (R5x/F5x/F6x), then everything else.
/**
 * Sort key for one series code: [kind, era, number, code].
 * @param {string} code - a vehicles.json series code
 * @returns {[number, number, number, string]}
 */
function seriesRank(code) {
  if (/^[EFGIU]\d/.test(code)) {
    // BMW car chassis: E46, F30, G20...
    const era = ETK_ERA_RANK[code[0]];
    const num = parseInt(code.slice(1), 10) || 0;
    return [0, era, num, code];
  }
  if (/^(R5|F5|F6)/.test(code)) return [1, 0, 0, code]; // MINI
  return [2, 0, 0, code]; // bikes / classics / internal codes
}

/**
 * Series codes sorted cars-first, then Minis, then everything else.
 * @param {string[]} codes - series codes
 * @returns {string[]} a new sorted array
 */
function seriesSort(codes) {
  return codes.slice().sort((a, b) => {
    const ra = seriesRank(a),
      rb = seriesRank(b);
    for (let i = 0; i < ra.length; i++) {
      if (ra[i] < rb[i]) return -1;
      if (ra[i] > rb[i]) return 1;
    }
    return 0;
  });
}

/**
 * Is this model name a motorcycle? R-/K-/C-prefixed engine names, or the
 * F/G three-digit bikes.
 * @param {string} model - a model name from vehicles.json
 * @returns {boolean}
 */
function etkIsBikeModel(model) {
  const m = model.trim();
  return /^[RKC]\s?\d/.test(m) || /^F \d{3}/.test(m) || /^G \d{3}/.test(m);
}

/**
 * The marketing-series key a model name votes for: X3 -> "X3", Z4 -> "Z",
 * M3 -> "M", 525i -> "5'", or null when it says nothing.
 * @param {string} model - a model name from vehicles.json
 * @returns {string|null}
 */
function etkModelSeriesKey(model) {
  const t = model.trim();
  const x = t.match(/^(X\d)/); // X3, X5
  if (x) return x[1];
  if (/^Z\d/.test(t)) return 'Z'; // Z3, Z4 -> one "Z" series
  if (/^M(\d)\b/.test(t)) return 'M'; // M3, M5
  if (/^\d/.test(t)) return t[0] + "'"; // 5xx -> 5'
  return null;
}

// ETK's Vehicle Identification lists a top-level marketing series ("5'", "X3",
// "MINI"...) which expands to the chassis under it (E60, E61, F10, F18...).
// The internal series codes in vehicles.json don't carry that grouping, so we
// derive it from each chassis's model names: the dominant model prefix names
// the series (5xx -> 5', X3 xx -> X3, "R 1200" -> Moto). This mirrors what a
// user sees on the dealer terminal without needing a hand-kept 296-row table.
/**
 * The marketing series one chassis belongs to.
 * @param {string} code - the chassis / series code
 * @param {Iterable<string>} models - every model name under that chassis
 * @returns {string} the series name ("5'", "X3", "Z", "M", "i", "MINI", "Moto", "Classic", "Other")
 */
function chassisSeries(code, models) {
  if (ETK_SERIES_HARD[code]) return ETK_SERIES_HARD[code];
  if (/^I\d/.test(code)) return 'i'; // i3 / i8
  if (/^(R5|R13|R56|R57|R58|R59|F5|F6)/.test(code)) return 'MINI';
  const list = [...models];
  const bike = list.filter(etkIsBikeModel).length;
  if (bike > list.length / 2) return 'Moto';
  const tally = {};
  for (const m of list) {
    const key = etkModelSeriesKey(m);
    if (key) tally[key] = (tally[key] || 0) + 1;
  }
  let best = null,
    n = -1;
  for (const k in tally)
    if (tally[k] > n) {
      n = tally[k];
      best = k;
    }
  return best || 'Other';
}

// order the marketing-series buckets the way ETK does: number series, then X,
// then Z, M, i, MINI, motorcycles, classics/other.
/**
 * Sort key for a series bucket: [bucket rank, number within the bucket].
 * @param {string} s - a series name
 * @returns {[number, number]}
 */
function seriesGroupRank(s) {
  if (/^\d'$/.test(s)) return [ETK_SERIES_RANK_NUMBER, parseInt(s, 10)];
  if (/^X\d$/.test(s)) return [ETK_SERIES_RANK_X, parseInt(s.slice(1), 10)];
  const named = ETK_SERIES_ORDER.indexOf(s);
  if (named >= 0) return [ETK_SERIES_RANK_NAMED + named, 0];
  return [ETK_SERIES_RANK_NAMED + ETK_SERIES_ORDER.length, 0];
}

/**
 * Group every chassis in the vehicle tree by marketing series, each bucket
 * sorted, buckets in ETK's display order.
 * @param {EtkVehicleTree} veh - the loaded vehicles.json
 * @returns {EtkSeriesGroups}
 */
function groupBySeries(veh) {
  const groups = {};
  for (const code of Object.keys(veh)) {
    const models = new Set();
    for (const body in veh[code])
      for (const m in veh[code][body]) models.add(m);
    const s = chassisSeries(code, models);
    (groups[s] = groups[s] || []).push(code);
  }
  const order = Object.keys(groups).sort((a, b) => {
    const ra = seriesGroupRank(a),
      rb = seriesGroupRank(b);
    return ra[0] - rb[0] || ra[1] - rb[1] || (a < b ? -1 : 1);
  });
  for (const s of order) groups[s] = seriesSort(groups[s]);
  return { order, groups };
}


;/* ==== screens/etk/vin.js ==== */
/**
 * @file VIN decoding. A BMW VIN's last 7 characters are the sequential
 * production number. vin-index maps each production-number range to a
 * vehicle, so a VIN resolves to its exact chassis + variant and the catalogue
 * (or the wiring viewer, which shares this) opens pre-filtered.
 */

/* exported VIN_PROD_LEN, loadVinIndex, decodeVin */

/**
 * The gzipped vin-index.json.
 * @typedef {object} EtkVinIndex
 * @property {[string, string, string, string, string, string][]} variants - [chassis, mospid, model, body, motor, steer]
 * @property {[string, string, number, string][]} ranges - [from, to, variant index, production date], sorted by `from`
 */

/**
 * A decoded VIN (or a vehicle picked by attributes, which produces the same
 * shape minus `motor`/`pn`). This is what the identify screen hands to its
 * `onResolve` and what the saved-vehicles panel stores.
 * @typedef {object} EtkVinHit
 * @property {string} [pn] - the 7-character production number
 * @property {string} chassis - chassis code
 * @property {string} [mospid] - ETK's internal vehicle id
 * @property {string} [model] - model name
 * @property {string} [body] - body code
 * @property {string} [motor] - engine code (VIN path only)
 * @property {string} [steer] - 'L' or 'R'
 * @property {string} [gear] - gearbox code (attribute path only)
 * @property {string} [prod] - production / introduction date as YYYYMMDD
 * @property {string} [vin] - the VIN as entered, upper-cased
 */

/** Length of the production number at the end of a BMW VIN. */
const VIN_PROD_LEN = 7;

/** @type {EtkVinIndex|null} */
let etkVinIndex = null;

/**
 * Load (and cache) the VIN index, gunzipping it in the browser.
 * @param {EtkProgressFn} [onProgress] - called as the file downloads
 * @returns {Promise<EtkVinIndex>}
 * @throws {Error} when neither copy is reachable
 */
async function loadVinIndex(onProgress) {
  if (etkVinIndex) return etkVinIndex;
  const hit = await etkFetchFirst('vin-index.json.gz');
  if (!hit) throw new Error('VIN data not available');
  const bytes = await readWithProgress(hit.resp, onProgress);
  const json = fflate.strFromU8(fflate.gunzipSync(bytes));
  etkVinIndex = JSON.parse(json);
  return etkVinIndex;
}

/**
 * Resolve a VIN (or a bare 7-character production number) to its vehicle.
 * The ranges are sorted by their start, so this binary-searches them.
 * @param {EtkVinIndex} idx - the loaded index
 * @param {string} vinRaw - the VIN as typed (whitespace and case are forgiven)
 * @returns {EtkVinHit|null} the vehicle, or null when no range covers the number
 */
function decodeVin(idx, vinRaw) {
  const vin = String(vinRaw || '')
    .trim()
    .toUpperCase()
    .replace(/\s/g, '');
  // last 7 chars are the production number; a bare 7-char code is accepted too
  const pn =
    vin.length >= VIN_PROD_LEN
      ? vin.slice(-VIN_PROD_LEN)
      : vin.padStart(VIN_PROD_LEN, '0');
  const R = idx.ranges;
  let lo = 0,
    hi = R.length - 1,
    hit = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    const [von, bis] = R[mid];
    if (pn < von) hi = mid - 1;
    else if (pn > bis) lo = mid + 1;
    else {
      hit = mid;
      break;
    }
  }
  if (hit < 0) return null;
  const [, , vi, prod] = R[hit];
  const v = idx.variants[vi]; // [chassis,mospid,model,body,motor,steer]
  return {
    pn,
    chassis: v[0],
    mospid: v[1],
    model: v[2],
    body: v[3],
    motor: v[4],
    steer: v[5],
    prod,
  };
}


;/* ==== screens/etk/attributes.js ==== */
/**
 * @file ETK's "Identification by attributes" group box, 1:1 with the dealer
 * terminal: a Brand / Prod. type / Catalogue filter row, then [Series* |
 * chassis] [Body* + car image] [Model* with Steering / Gearbox / Year / Month
 * in a 2x2 beneath it], go-arrow bottom right. Each pick fills the next pane
 * from vehicles.json; the pure steps (series filter, year expansion, newest
 * intro year) are separate so they can be checked without a DOM.
 */

/* exported etkAttributeSelector */

/**
 * The series filter result: one marketing series and the chassis under it.
 * @typedef {{ series: string, codes: string[] }} EtkSeriesEntry
 */

/**
 * The year digits of a YYYYMMDD date.
 * @param {string|number} d - the date
 * @returns {string}
 */
function etkYearOf(d) {
  return String(d).slice(0, 4);
}

/**
 * The month digits of a YYYYMMDD date.
 * @param {string|number} d - the date
 * @returns {string}
 */
function etkMonthOf(d) {
  return String(d).slice(4, 6);
}

/**
 * The value a cascade select currently holds, read back through its `_vals`
 * sidecar (the raw codes behind the displayed labels); null when nothing is
 * picked.
 * @param {EtkSelect} sel - a makeSelect() control with `_vals` set
 * @returns {string|null}
 */
function etkSelValue(sel) {
  return sel._vals && sel.value !== '' ? sel._vals[+sel.value] : null;
}

/**
 * A labelled column wrapper (a heading over a list box or dropdown).
 * @param {string} labelText - the heading
 * @param {HTMLElement} el - the control beneath it
 * @param {string} [cls] - extra class on the column
 * @returns {HTMLDivElement}
 */
function etkLabelledCol(labelText, el, cls) {
  const c = document.createElement('div');
  c.className = 'etk-idcol' + (cls ? ' ' + cls : '');
  const l = document.createElement('span');
  l.className = 'etk-idlabel';
  l.textContent = labelText;
  c.append(l, el);
  return c;
}

/**
 * The filter row over the attribute selector: Brand dropdown + Auto/Moto
 * radios + Main/Classic radios. These narrow which series show, same as the
 * terminal's selectors.
 * @returns {{
 *   el: HTMLDivElement,
 *   prodType: () => string,
 *   scope: () => string,
 *   brand: () => string,
 *   onChange: (fn: () => void) => void,
 * }}
 */
function etkAttrFilters() {
  const el = document.createElement('div');
  el.className = 'etk-idfilters';
  el.innerHTML = `
    <div class="etk-idfilter etk-idfilter-brand"><span class="etk-idflabel">Brand</span></div>
    <div class="etk-idfilter"><span class="etk-idflabel">Prod. type</span>
      <label class="etk-idradio"><input type="radio" name="etk-ptype" value="auto" checked> Auto</label>
      <label class="etk-idradio"><input type="radio" name="etk-ptype" value="moto"> Moto</label>
    </div>
    <div class="etk-idfilter"><span class="etk-idflabel">Catalogue</span>
      <label class="etk-idradio"><input type="radio" name="etk-scope" value="main" checked> Main catalogue</label>
      <label class="etk-idradio"><input type="radio" name="etk-scope" value="classic"> BMW Classic</label>
    </div>
    <span class="etk-idreq">* required attributes</span>`;
  const selBrand = makeSelect('BMW');
  selBrand.setOptions(['BMW', 'MINI'], 'BMW');
  selBrand.selectedIndex = 1; // BMW preselected
  el.querySelector('.etk-idfilter-brand').appendChild(selBrand);
  return {
    el,
    prodType: () => el.querySelector('input[name="etk-ptype"]:checked').value,
    scope: () => el.querySelector('input[name="etk-scope"]:checked').value,
    brand: () => (selBrand.value === '1' ? 'MINI' : 'BMW'),
    onChange: (fn) => {
      el.querySelectorAll('input[type="radio"]').forEach((r) => {
        r.onchange = fn;
      });
      selBrand.onchange = fn;
    },
  };
}

// A code is "classic" when it isn't a modern car chassis code (E/F/G/I/U +
// digits): the raw numeric and letter codes (114, 700, NK, V8...) are the
// old-timers BMW Classic covers, plus the hard-bucketed Classic group.
/**
 * Does BMW Classic (rather than the main catalogue) cover this chassis?
 * @param {string} code - chassis code
 * @param {string} series - its marketing series
 * @returns {boolean}
 */
function etkIsClassicCode(code, series) {
  // Z covers the literal Z1/Z3 chassis codes
  return (
    series === 'Classic' || series === 'Other' || !/^[EFGIUZ]\d/.test(code)
  );
}

/**
 * The series (and the chassis under each) the Brand / Prod. type / Catalogue
 * filters leave visible.
 * @param {EtkSeriesGroups} grouped - every series
 * @param {string} type - 'auto' | 'moto'
 * @param {string} brand - 'BMW' | 'MINI'
 * @param {string} scope - 'main' | 'classic'
 * @returns {EtkSeriesEntry[]}
 */
function etkVisibleSeries(grouped, type, brand, scope) {
  const out = [];
  for (const s of grouped.order) {
    let codes = grouped.groups[s];
    if (type === 'moto') {
      if (s !== 'Moto') continue;
    } else {
      if (s === 'Moto') continue;
      if (brand === 'MINI') {
        if (s !== 'MINI') continue;
      } else {
        if (s === 'MINI') continue;
        codes = codes.filter(
          (c) => etkIsClassicCode(c, s) === (scope === 'classic')
        );
      }
    }
    if (codes.length) out.push({ series: s, codes });
  }
  return out;
}

/**
 * Newest introduction year across every body / model of a chassis -- a
 * stand-in for end-of-build, so the Year list can run past the last per-model
 * introduction date.
 * @param {Record<string, Record<string, EtkVehicleRow[]>>} bodies - the chassis node of the vehicle tree
 * @returns {number} the year, or 0 when no row carries one
 */
function etkMaxIntroYear(bodies) {
  let max = 0;
  for (const mods of Object.values(bodies)) {
    for (const variants of Object.values(mods)) {
      for (const v of variants) {
        const y = +etkYearOf(v[2]);
        if (y && y > max) max = y;
      }
    }
  }
  return max;
}

/** @type {Map<string, number>|null} memoised end-of-build years */
let etkProdEndCache = null;

/**
 * Each variant's real end-of-build year, taken from the VIN index. vehicles.json
 * carries only an introduction date, so etkMaxIntroYear is a chassis-wide
 * stand-in that runs every variant to the same year -- too long for a model
 * that stopped early (an M3 CSL built only in 2003) and too short for one that
 * outlived the newest introduction. The VIN index records every
 * production-number block with its date, so a variant's newest block is its
 * true end of build. Built once, keyed "chassis|mospid|steer".
 * @param {EtkVinIndex} idx - the loaded VIN index
 * @returns {Map<string, number>} key -> end-of-production year
 */
function etkProdEndYears(idx) {
  if (etkProdEndCache) return etkProdEndCache;
  const byVariant = []; // variant index -> newest production year
  for (const r of idx.ranges) {
    const y = +String(r[3]).slice(0, 4);
    if (y && y > (byVariant[r[2]] || 0)) byVariant[r[2]] = y;
  }
  const out = new Map();
  idx.variants.forEach((v, i) => {
    const y = byVariant[i];
    if (!y) return;
    const key = `${v[0]}|${v[1]}|${v[5]}`;
    if (y > (out.get(key) || 0)) out.set(key, y);
  });
  etkProdEndCache = out;
  return out;
}

/**
 * The newest end-of-build year across a set of variant rows, for the Year
 * list's upper bound. Falls back to the chassis-wide stand-in until the VIN
 * index is loaded, or for any variant it does not cover.
 * @param {EtkVehicleRow[]} vs - the filtered variant rows ([steer,gear,date,mospid])
 * @param {string} chassis - the chassis code
 * @param {Map<string, number>|null} prodEnds - the loaded end-of-build map, or null
 * @param {number} fallback - the chassis-wide stand-in (etkMaxIntroYear)
 * @returns {number}
 */
function etkVariantEndYear(vs, chassis, prodEnds, fallback) {
  if (!prodEnds) return fallback;
  let end = 0;
  for (const v of vs) {
    const y = prodEnds.get(`${chassis}|${v[3]}|${v[0]}`);
    if (y && y > end) end = y;
  }
  return end || fallback;
}

// The dates in the data are each variant's INTRODUCTION date, not the model
// years it was sold. So a car whose build year sits between two intro dates
// (a 2005 E46 325i, say) had no exact row and its year went missing from the
// list. List every year from the first intro to the chassis's end of build,
// and map each to the variant "in force" then (newest intro <= that year).
/**
 * Expand introduction years into every sellable year, each mapped to the
 * introduction year of the variant in force then.
 * @param {string[]} introYears - distinct introduction years, sorted ascending
 * @param {number} maxYear - the chassis's end-of-build stand-in
 * @returns {{ years: string[], byYear: Record<string, string>|null }} byYear is null when there were no intro years
 */
function etkYearsInForce(introYears, maxYear) {
  if (!introYears.length) return { years: introYears, byYear: null };
  const lo = +introYears[0];
  const hi = Math.max(+introYears[introYears.length - 1], maxYear || 0);
  const years = [];
  const byYear = {};
  for (let y = lo; y <= hi; y++) {
    const ys = String(y);
    // the newest intro-year at or before y -- the variant valid that year
    const inForce = introYears.filter((iy) => +iy <= y).pop();
    if (inForce) {
      years.push(ys);
      byYear[ys] = inForce;
    }
  }
  return { years, byYear };
}

/**
 * ETK's lower group box, "Identification by attributes", 1:1 with the
 * terminal: a Brand / Prod. type / Catalogue filter row, then [Series* |
 * chassis] [Body* + car image] [Model* with Steering / Gearbox / Year / Month
 * in a 2x2 beneath it], go-arrow bottom right. Each pick fills the next pane.
 * @param {EtkIdentifyOpts} opts - section overrides (the gate and its message)
 * @param {(hit: EtkVinHit) => void} onResolve - opens the picked vehicle
 * @returns {HTMLFieldSetElement}
 */
function etkAttributeSelector(opts, onResolve) {
  const idCard = document.createElement('fieldset');
  idCard.className = 'etk-fs etk-fs-attr';
  const idLegend = document.createElement('legend');
  idLegend.textContent = 'Identification by attributes';
  idCard.appendChild(idLegend);

  const filters = etkAttrFilters();
  idCard.appendChild(filters.el);

  // the ETK cascade's list boxes use the shared control (ui/listbox.js),
  // focusable for keyboard navigation
  const listBox = () => makeListBox({ focusable: true });
  const lbSeries = listBox();
  const lbChassis = listBox();
  const lbBody = listBox();
  const lbModel = listBox();
  const selSteer = makeSelect('All values');
  const selGear = makeSelect('All values');
  const selYear = makeSelect('All values');
  const selMonth = makeSelect('All values');
  [selSteer, selGear, selYear, selMonth].forEach((s) => {
    s.disabled = true;
  });

  // ETK's positioning: [Series | Chassis] paired on the left, then Body (with a
  // vehicle thumbnail beneath it), then Model on the right with the Steering /
  // Transmission / Year dropdowns tucked underneath the Model column.
  const lists = document.createElement('div');
  lists.className = 'etk-idlists';

  // left block: Series + chassis sitting flush together (ETK labels only the
  // Series pane; the chassis pane is its unlabelled expansion)
  const leftBlock = document.createElement('div');
  leftBlock.className = 'etk-idpair';
  leftBlock.append(
    etkLabelledCol('Series*', lbSeries, 'etk-idcol-series'),
    etkLabelledCol(' ', lbChassis, 'etk-idcol-chassis')
  );

  // middle block: Body, with the car image beneath it
  const midBlock = document.createElement('div');
  midBlock.className = 'etk-idmid';
  const thumb = document.createElement('div');
  thumb.className = 'etk-idthumb';
  thumb.hidden = true;
  midBlock.append(etkLabelledCol('Body*', lbBody), thumb);

  // right block: Model on top, the 2x2 dropdowns beneath it (ETK's Steering |
  // Gearbox on the first row, Year | Month on the second)
  const rightBlock = document.createElement('div');
  rightBlock.className = 'etk-idright';
  const drops = document.createElement('div');
  drops.className = 'etk-iddrops';
  drops.append(
    etkLabelledCol('Steering', selSteer),
    etkLabelledCol('Gearbox', selGear),
    etkLabelledCol('Year', selYear),
    etkLabelledCol('Month', selMonth)
  );
  rightBlock.append(etkLabelledCol('Model*', lbModel), drops);

  lists.append(leftBlock, midBlock, rightBlock);

  const foot = document.createElement('div');
  foot.className = 'etk-idfoot';
  const idHint = document.createElement('span');
  idHint.className = 'etk-idhint';
  idHint.textContent = 'Loading vehicles…';
  const idOpen = document.createElement('button');
  idOpen.type = 'button';
  idOpen.className = 'etk-vin-go etk-idgo';
  idOpen.hidden = true;
  idOpen.setAttribute('aria-label', 'Open parts catalogue');
  idOpen.textContent = '→';
  foot.append(idHint, idOpen);

  idCard.append(lists, foot);

  /** @type {EtkVehicleTree|null} the loaded vehicles.json */
  let veh = null;
  /** @type {EtkSeriesGroups|null} */
  let grouped = null;
  /** @type {EtkVinHit|null} the vehicle the current picks resolve to */
  let picked = null;
  let chassisMaxYear = 0; // newest intro-year anywhere in the chassis
  /** @type {Map<string, number>|null} per-variant end-of-build from the VIN index */
  let prodEnds = null;
  const state = {
    series: null,
    chassis: null,
    body: null,
    model: null,
    /** @type {Record<string, string[]>} series -> chassis codes after the filters */
    codesBySeries: {},
    /** @type {EtkVehicleRow[]} the picked model's rows */
    variants: [],
  };

  /** Clear the four dropdowns and hide the go arrow. */
  function resetDrops() {
    picked = null;
    idOpen.hidden = true;
    [selSteer, selGear, selYear, selMonth].forEach((s) => {
      s.setDisabledEmpty();
      s.disabled = true;
    });
  }

  // ---- the Brand / Prod. type / Catalogue filters narrow the Series pane ----
  /** Refill the Series pane from the filters and clear everything after it. */
  function refreshSeries() {
    if (!grouped) return;
    const out = etkVisibleSeries(
      grouped,
      filters.prodType(),
      filters.brand(),
      filters.scope()
    );
    state.series = state.chassis = state.body = state.model = null;
    state.codesBySeries = Object.fromEntries(
      out.map((o) => [o.series, o.codes])
    );
    lbChassis.clear();
    lbBody.clear();
    lbModel.clear();
    resetDrops();
    thumb.hidden = true;
    lbSeries.setItems(out.map((o) => ({ key: o.series, label: o.series })));
    idHint.textContent = 'Pick a series to begin.';
  }
  filters.onChange(refreshSeries);

  // Series picked -> fill Chassis
  lbSeries.onpick = (series) => {
    state.series = series;
    state.chassis = state.body = state.model = null;
    lbBody.clear();
    lbModel.clear();
    resetDrops();
    thumb.hidden = true;
    lbChassis.setItems(
      state.codesBySeries[series].map((c) => ({
        key: c,
        label: dispChassis(c),
      }))
    );
    idHint.textContent = 'Pick a chassis.';
  };

  // swap the placeholder silhouette for the real ETK car photo when we have
  // one for this chassis+body (thumbs.json indexes what shipped)
  /**
   * @param {string|null} ch - chassis code
   * @param {string|null} body - body code
   */
  function setThumb(ch, body) {
    const url = etkThumbUrl(ch, body);
    if (url) {
      thumb.style.background = `var(--bg) url("${url}") center/contain no-repeat`;
      thumb.classList.add('etk-idthumb-photo');
    } else {
      thumb.style.background = '';
      thumb.classList.remove('etk-idthumb-photo');
    }
  }

  // Chassis picked -> fill Body
  lbChassis.onpick = (ch) => {
    state.chassis = ch;
    state.body = state.model = null;
    lbModel.clear();
    resetDrops();
    thumb.hidden = false;
    setThumb(null, null);
    // the upper bound for the (expanded) Year dropdown, since no explicit end
    // date exists
    chassisMaxYear = etkMaxIntroYear(veh[ch]);
    const bodies = Object.keys(veh[ch]);
    lbBody.setItems(bodies.map((b) => ({ key: b, label: bodyLabel(b) })));
    idHint.textContent = 'Pick a body style.';
  };
  // Body picked -> fill Model (and show that body's car photo)
  lbBody.onpick = (body) => {
    state.body = body;
    state.model = null;
    resetDrops();
    setThumb(state.chassis, body);
    const models = Object.keys(veh[state.chassis][body]);
    lbModel.setItems(models.map((m) => ({ key: m, label: m })));
    idHint.textContent = 'Pick a model.';
  };
  // Model picked -> fill the Steering / Gearbox / Year / Month dropdowns
  lbModel.onpick = (model) => {
    state.model = model;
    resetDrops();
    const variants = veh[state.chassis][state.body][model]; // [[steer,gear,date,mospid]]
    state.variants = variants;
    const steers = [...new Set(variants.map((v) => v[0]))].filter(Boolean);
    selSteer.setOptions(
      steers.map(etkSteerLabel),
      steers.length > 1 ? 'All values' : ''
    );
    selSteer._vals = steers;
    selSteer.disabled = false;
    if (steers.length === 1) {
      selSteer.selectedIndex = 1;
    }
    selSteer.onchange();
  };

  selSteer.onchange = () => {
    [selGear, selYear, selMonth].forEach((s) => {
      s.setDisabledEmpty();
      s.disabled = true;
    });
    const steer = etkSelValue(selSteer);
    const vs = state.variants.filter((v) => !steer || v[0] === steer);
    const gears = [...new Set(vs.map((v) => v[1]))].filter(Boolean);
    selGear.setOptions(
      gears.map(etkGearLabel),
      gears.length > 1 ? 'All values' : ''
    );
    selGear._vs = vs;
    selGear._vals = gears;
    selGear.disabled = false;
    if (gears.length === 1) {
      selGear.selectedIndex = 1;
    }
    selGear.onchange();
  };
  selGear.onchange = () => {
    [selYear, selMonth].forEach((s) => {
      s.setDisabledEmpty();
      s.disabled = true;
    });
    const gear = etkSelValue(selGear);
    const vs = selGear._vs.filter((v) => !gear || v[1] === gear);
    const introYears = [...new Set(vs.map((v) => etkYearOf(v[2])))]
      .filter(Boolean)
      .sort();
    const maxYear = etkVariantEndYear(
      vs,
      state.chassis,
      prodEnds,
      chassisMaxYear
    );
    const { years, byYear } = etkYearsInForce(introYears, maxYear);
    selYear.setOptions(years, years.length > 1 ? 'All values' : '');
    selYear._vs = vs;
    selYear._vals = years;
    selYear._byYear = byYear;
    selYear.disabled = false;
    if (years.length === 1) {
      selYear.selectedIndex = 1;
    }
    selYear.onchange();
  };
  selYear.onchange = () => {
    selMonth.setDisabledEmpty();
    selMonth.disabled = true;
    const yearPick = etkSelValue(selYear);
    // resolve the displayed year to the intro-year of the variant in force
    const introYear =
      yearPick && selYear._byYear ? selYear._byYear[yearPick] : yearPick;
    const vs = selYear._vs.filter(
      (v) => !introYear || etkYearOf(v[2]) === introYear
    );
    const months = [...new Set(vs.map((v) => etkMonthOf(v[2])))]
      .filter(Boolean)
      .sort();
    selMonth.setOptions(months, months.length > 1 ? 'All values' : '');
    selMonth._vs = vs;
    selMonth._vals = months;
    selMonth.disabled = false;
    if (months.length === 1) {
      selMonth.selectedIndex = 1;
    }
    recompute();
  };
  selMonth.onchange = recompute;

  // pick the most specific variant the current filters allow; show the go
  // arrow once a vehicle resolves (with "All values" left alone it takes the
  // first match, same as the terminal's behaviour).
  /** Resolve the current picks to a vehicle and show / hide the go arrow. */
  function recompute() {
    let vs = state.variants || [];
    const steer = etkSelValue(selSteer);
    if (steer) vs = vs.filter((v) => v[0] === steer);
    const gear = etkSelValue(selGear);
    if (gear) vs = vs.filter((v) => v[1] === gear);
    const yearSel = etkSelValue(selYear);
    // displayed year -> the intro-year of the variant in force (see selGear.onchange)
    const year =
      yearSel && selYear._byYear ? selYear._byYear[yearSel] : yearSel;
    if (year) vs = vs.filter((v) => etkYearOf(v[2]) === year);
    const month = etkSelValue(selMonth);
    if (month) vs = vs.filter((v) => etkMonthOf(v[2]) === month);
    const v = vs[0];
    if (!v || !state.model) {
      picked = null;
      idOpen.hidden = true;
      return;
    }
    picked = {
      chassis: state.chassis,
      mospid: v[3],
      model: state.model,
      body: state.body,
      steer: v[0],
      gear: v[1],
      prod: v[2],
    };
    idHint.textContent =
      `${dispChassis(picked.chassis)} · ${picked.model} · ` +
      `${bodyLabel(picked.body)} · ${etkSteerLabel(picked.steer)}`;
    idOpen.hidden = false;
  }

  idOpen.onclick = async () => {
    if (!picked) return;
    // the section may not cover this manually-picked chassis (wiring)
    const canOpen = opts.resolvable
      ? await opts.resolvable(picked.chassis)
      : true;
    if (!canOpen) {
      idHint.textContent = opts.unavailable
        ? opts.unavailable(dispChassis(picked.chassis))
        : `Not available for ${dispChassis(picked.chassis)}.`;
      return;
    }
    onResolve(picked);
  };

  // populate the Series pane once vehicles.json is in hand (car photos load
  // alongside; missing thumbs just leave the silhouette)
  (async () => {
    try {
      loadEtkThumbs();
      veh = await loadVehicles();
      grouped = groupBySeries(veh);
      refreshSeries();
      // The Year list needs each variant's real end of build, which lives in
      // the VIN index (vehicles.json has only intro dates). Pull it in the
      // background so it never blocks the picker; until it lands the list uses
      // the chassis-wide stand-in, and once it does a shown list is rebuilt.
      loadVinIndex()
        .then((idx) => {
          prodEnds = etkProdEndYears(idx);
          if (state.model && !selGear.disabled) selGear.onchange();
        })
        .catch(() => {}); // optional here: the stand-in still works without it
    } catch (e) {
      idHint.textContent = String(e.message || e);
    }
  })();

  return idCard;
}


