  // module without a module name outranking the key the user asked for
  const weak = [
    e.c,
    e.ce,
    (e.k || []).join(' '),
    e.s,
    e.m,
    mod.sgbd,
    mod.label,
    mod.code,
  ]
    .filter(Boolean)
    .join(' ')
    .toLowerCase();
  const jobs = (e.j || []).map((j) => j.toLowerCase());
  return { strong, weak, jobs };
