    const lx = lineX(line.col);
    const y = box.y + box.h / 2;
    const left = lx < box.x;
    stubs.push({
      bus: line.bus,
      x1: left ? lx : box.x + box.w,
      x2: left ? box.x : lx,
      y,
    });
