        `<div class="quick-detail-row${f.present ? ' present' : ''}">` +
        `<span class="quick-detail-code">${esc(f.code)}</span>` +
        `<span class="quick-detail-name">${esc(f.name)}</span>` +
        `<span class="quick-detail-state">${f.present ? 'PRESENT' : 'stored'}</span></div>`
