  const legendSlot = wrap.querySelector('.tree-legend-slot');
  const scanBtn = wrap.querySelector('.tree-scan');
  const stopBtn = wrap.querySelector('.tree-stop');
  const progress = wrap.querySelector('.tree-progress');

