    const b = tnSelectionBounds(m.sel);
    if (!b) return;
    const tsv = tnCellsTsv(m.t.cells, b, m.dp);
    e.preventDefault();
    e.clipboardData.setData('text/plain', tsv.text);
    tnTableFlashInfo(m, `copied ${tsv.rows} × ${tsv.cols}`);
