  lt: null,
  busy: false,
  error: null,
  ed: null,
  els: null,
  cell: 1,
  suppressWrite: false, // set while folding an ECU read-back in, so it does not loop
  note: '', // what the last edit could not do live
  progress: '', // what a slow step on the ECU is doing (making room)
