      const cx = x(this.cursorT);
      ctx.strokeStyle = c.ink;
      ctx.globalAlpha = 0.5;
      ctx.beginPath();
      ctx.moveTo(cx, 0);
      ctx.lineTo(cx, cssH);
      ctx.stroke();
      ctx.globalAlpha = 1;
