            const x = left + c * colW;
            const y = top + 4 + lineH * r + lineH / 2;
            g.fillStyle = colour(m.i);
            g.beginPath();
            g.arc(x + 9, y, 2.5, 0, Math.PI * 2);
            g.fill();
            g.fillStyle = theme.ink;
            g.fillText(texts[k], x + 16, y);
