if (typeof window !== 'undefined') {
  window.istaAblWindow = istaAblWindow;
}

if (typeof module !== 'undefined')
  module.exports = {
    istaAblWindow,
    istaAblStepHtml,
    istaAblDocPanes,
    ISTA_ABL_STATE,
  };


