  const c = car === undefined ? istaState.car : car;
  if (typeof istaPlanRows !== 'function') return [];
  return typeof istaPlanSort === 'function'
    ? istaPlanSort(istaPlanRows(c), istaState.planDesc)
    : istaPlanRows(c);
